package com.ne.business.dflq.triggered.aspect;

import com.ne.boot.common.util.JsonUtil;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.stereotype.Component;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;
import org.springframework.web.multipart.MultipartFile;

import javax.servlet.http.HttpServletRequest;
import java.io.InputStream;
import java.util.Enumeration;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * @author zhi.luo
 * @date 2023/10/18 15:51
 */
@Aspect
@Component
public class LoggingAspect {

    private static final Logger log = LoggerFactory.getLogger(LoggingAspect.class);

    /**
     * 拦截controller层并且有RequestMapping注释的方法
     *
     * @param joinPoint ProceedingJoinPoint
     * @return Object
     * @throws Throwable e
     */

    @Around("execution(* com.ne.business.dflq.triggered.controller..*.*(..))"
            + "|| @annotation(org.springframework.web.bind.annotation.GetMapping) "
            + "|| @annotation(org.springframework.web.bind.annotation.PostMapping) ")
    public Object aroundAdvice(ProceedingJoinPoint joinPoint) throws Throwable {
        MDC.put("traceId", UUID.randomUUID().toString());
        HttpServletRequest request = ((ServletRequestAttributes) RequestContextHolder.getRequestAttributes()).getRequest();
        String requestURI = request.getMethod() + " " + request.getRequestURI();

        Object args = joinPoint.getArgs();
        if ("GET".equals(request.getMethod())) {
            args = getRequestParameters(request);
        }
        String argsJsonStr = JsonUtil.writeValueAsString(filterUnserializableObjects(args));

        log.info("{} - start, args: {} ", requestURI, argsJsonStr);

        long start = System.currentTimeMillis();
        try {
            Object result = joinPoint.proceed();
            long timeConsuming = System.currentTimeMillis() - start;
            if (argsJsonStr.length() > 100) {
                argsJsonStr = argsJsonStr.substring(0, 100) + "...";
            }
            log.info("{} - end, cost:{}ms, res:{} - args: {}", requestURI, timeConsuming,
                    JsonUtil.writeValueAsString(result), argsJsonStr);
            return result;
        } catch (Exception e) {
            // 如果原方法抛出异常，记录异常信息
            log.error("Exception - {} - args:{}", requestURI, argsJsonStr);
            throw e;
        } finally {
            long tt = 5000;
            long timeConsuming = System.currentTimeMillis() - start;
            if (timeConsuming > tt) {
                log.error("{} - end, args: {} cost too long:{}ms ", requestURI, argsJsonStr, timeConsuming);
            }
            MDC.clear();
        }
    }

    public Map<String, String> getRequestParameters(HttpServletRequest request) {
        Map<String, String> res = new HashMap<>();
        Enumeration<String> parameterNames = request.getParameterNames();
        while (parameterNames.hasMoreElements()) {
            String paramName = parameterNames.nextElement();
            String[] paramValues = request.getParameterValues(paramName);
            for (String paramValue : paramValues) {
                res.put(paramName, paramValue);
            }
        }
        return res;
    }

    private Object filterUnserializableObjects(Object obj) {
        if (obj == null) {
            return null;
        }

        if (obj instanceof MultipartFile) {
            MultipartFile file = (MultipartFile) obj;
            Map<String, Object> fileInfo = new HashMap<>();
            fileInfo.put("fileName", file.getOriginalFilename());
            fileInfo.put("fileSize", file.getSize());
            fileInfo.put("contentType", file.getContentType());
            fileInfo.put("isEmpty", file.isEmpty());
            return fileInfo;
        }

        if (obj instanceof InputStream) {
            return "<InputStream>";
        }

        if (obj.getClass().getName().contains("FileDescriptor")) {
            return "<FileDescriptor>";
        }

        if (obj instanceof Object[]) {
            Object[] array = (Object[]) obj;
            Object[] filteredArray = new Object[array.length];
            for (int i = 0; i < array.length; i++) {
                filteredArray[i] = filterUnserializableObjects(array[i]);
            }
            return filteredArray;
        }

        return obj;
    }

}

