181	        if (CollectionUtils.isEmpty(triggeredEventIds)) {
182	            return clearEventList;
183	        }
184	        for (Long triggeredEventId : triggeredEventIds) {
185	            if (triggeredEventId == null) {
186	                continue;
187	            }
188	            PredictiveEventInfoVo clearEvent = new PredictiveEventInfoVo();
189	            clearEvent.setPredictiveEventId(triggeredEventId);
