196	    private List<PredictiveEventInfoVo> getPredictiveEventInfoVoList(List<Long> triggeredEventIds){
197	        List<PredictiveEventInfoVo> predictiveEventInfoVoList = Lists.newArrayList();
198	        if (triggeredEventIds == null) {
199	            return predictiveEventInfoVoList;
200	        }
201	        for (Long triggeredEventId : triggeredEventIds){
202	            //预知事件
203	            TriggeredEventPo triggeredEventPo = triggeredEventDao.getById(triggeredEventId);
204	            //事件规则
205	            TriggeredRulePo rulePo = triggeredRuleService.queryById(triggeredEventPo.getRuleId());
206	
207	            PredictiveEventInfoVo eventInfoVo = new PredictiveEventInfoVo();
208	            eventInfoVo.setPredictiveEventId(triggeredEventId);
209	            eventInfoVo.setEventRuleId(rulePo.getId());
210	
211	            //获取逻辑节点
212	            List<TriggeredEventRuleVo> eventRuleVoList = triggeredEventRuleService.getEventRuleByRuleId(triggeredEventId, rulePo.getId());
213	            Integer logicTreeNodeCount = 0;
