package com.ne.business.dflq.triggered.service.impl;


import com.alibaba.fastjson.JSONObject;
import com.ne.boot.common.entity.Response;
import com.ne.business.dflq.triggered.dao.TriggeredEventDao;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleDao;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleModelDao;
import com.ne.business.dflq.triggered.entity.dto.TriggeredVehicleDTO;
import com.ne.business.dflq.triggered.entity.dto.TriggeredVehicleModelDTO;
import com.ne.business.dflq.triggered.entity.mysql.DataItemPo;
import com.ne.business.dflq.triggered.entity.mysql.TriggeredEventPo;
import com.ne.business.dflq.triggered.entity.mysql.TriggeredRulePo;
import com.ne.business.dflq.triggered.feign.entity.PredictiveEventParamVo;
import com.ne.business.dflq.triggered.entity.vo.TriggeredEventRuleVo;
import com.ne.business.dflq.triggered.enums.ComparisonOperatorEnum;
import com.ne.business.dflq.triggered.enums.LogicOperatorEnum;
import com.ne.business.dflq.triggered.enums.RuleNode;
import com.ne.business.dflq.triggered.feign.DflzApiFeign;
import com.ne.business.dflq.triggered.service.*;
import com.ne.ice.tbox.protocol.vo.ComparisonSubexpressionInfoVo;
import com.ne.ice.tbox.protocol.vo.LogicTreeNodeInfoVo;
import com.ne.ice.tbox.protocol.vo.PredictiveEventInfoVo;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.compress.utils.Lists;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * - @ClassName: PredictiveEventSyncImpl
 * - @Des: 预知事件同步
 * - @Author: xhy
 * - @Date: 2026/3/11 13:28
 **/
@Slf4j
@Service
public class PredictiveEventSyncServiceImpl implements PredictiveEventSyncService {

    @Autowired
    TriggeredEventDao triggeredEventDao;
    @Autowired
    TriggeredVehicleDao triggeredVehicleDao;
    @Autowired
    TriggeredVehicleModelDao triggeredVehicleModelDao;
    @Autowired
    TriggeredEventRuleService triggeredEventRuleService;
    @Autowired
    DataItemDecodeRuleService dataItemDecodeRuleService;
    @Autowired
    DflzApiFeign dflzApiFeign;
    @Autowired
    VehicleModelMatlabService vehicleModelMatlabService;
    @Autowired
    DataItemService dataItemService;
    @Autowired
    TriggeredRuleService triggeredRuleService;

    @Override
    public Response predictiveVehicleEventSync(TriggeredVehicleDTO dto) {
        PredictiveEventParamVo paramVo = new PredictiveEventParamVo();
        paramVo.setVinList(dto.getVins());

        // 获取最新的全集预知事件
        List<Long> triggeredEventIds = dto.getTriggeredEventIds();
        List<PredictiveEventInfoVo> predictiveEventInfoVoList = getPredictiveEventInfoVoList(triggeredEventIds);
        paramVo.setPredictiveEventInfoVoList(predictiveEventInfoVoList);

        log.info("请求预知事件同步接口:{}", JSONObject.toJSONString(paramVo));
        return dflzApiFeign.predictiveEventSync(paramVo);
    }

    @Override
    public Response predictiveVehicleModelEventSync(TriggeredVehicleModelDTO dto) {
        PredictiveEventParamVo paramVo = new PredictiveEventParamVo();
        List<Integer> modelId = vehicleModelMatlabService.queryIdsByModelCodes(dto.getModelCodes());
        paramVo.setModelMatlabIdList(modelId);

        // 获取最新的全集预知事件
        List<Long> triggeredEventIds = dto.getTriggeredEventIds();
        List<PredictiveEventInfoVo> predictiveEventInfoVoList = getPredictiveEventInfoVoList(triggeredEventIds);
        paramVo.setPredictiveEventInfoVoList(predictiveEventInfoVoList);

        log.info("请求预知事件同步接口:{}", JSONObject.toJSONString(paramVo));
        return dflzApiFeign.predictiveEventSync(paramVo);
    }

    @Override
    public void clearPredictiveEventSync(Long triggeredEventId) {
        if (triggeredEventId == null) {
            log.warn("clear predictive event sync ignored, triggeredEventId is null");
            return;
        }

        List<PredictiveEventInfoVo> clearEventList = buildClearPredictiveEventList(triggeredEventId);
        Exception syncException = null;

        List<String> vins = triggeredVehicleDao.queryVinListByTriggeredEventId(triggeredEventId);
        if (CollectionUtils.isNotEmpty(vins)) {
            PredictiveEventParamVo vinParamVo = new PredictiveEventParamVo();
            vinParamVo.setVinList(vins);
            vinParamVo.setPredictiveEventInfoVoList(clearEventList);
            try {
                log.info("request clear predictive event sync:{}", JSONObject.toJSONString(vinParamVo));
                dflzApiFeign.predictiveEventSync(vinParamVo);
            } catch (Exception e) {
                syncException = e;
                log.error("request clear predictive event sync failed, triggeredEventId:{}, vins:{}",
                        triggeredEventId, JSONObject.toJSONString(vins), e);
            }
        }

        List<String> modelCodes = triggeredVehicleModelDao.queryModelCodeListByTriggeredEventId(triggeredEventId);
        if (CollectionUtils.isNotEmpty(modelCodes)) {
            try {
                List<Integer> modelMatlabIds = vehicleModelMatlabService.queryIdsByModelCodes(modelCodes);
                if (CollectionUtils.isNotEmpty(modelMatlabIds)) {
                    PredictiveEventParamVo modelParamVo = new PredictiveEventParamVo();
                    modelParamVo.setModelMatlabIdList(modelMatlabIds);
                    modelParamVo.setPredictiveEventInfoVoList(clearEventList);
                    log.info("request clear predictive event sync:{}", JSONObject.toJSONString(modelParamVo));
                    dflzApiFeign.predictiveEventSync(modelParamVo);
                }
            } catch (Exception e) {
                syncException = e;
                log.error("request clear predictive event sync failed, triggeredEventId:{}, modelCodes:{}",
                        triggeredEventId, JSONObject.toJSONString(modelCodes), e);
            }
        }

        if (syncException != null) {
            throw new RuntimeException("clear predictive event sync failed", syncException);
        }
    }

    private List<PredictiveEventInfoVo> buildClearPredictiveEventList(Long triggeredEventId) {
        return buildClearPredictiveEventList(Collections.singletonList(triggeredEventId));
    }

    @Override
    public void clearPredictiveEventSyncByVin(String vin, List<Long> triggeredEventIds) {
        if (StringUtils.isBlank(vin) || CollectionUtils.isEmpty(triggeredEventIds)) {
            log.warn("clear predictive event sync by vin ignored, vin:{}, triggeredEventIds:{}",
                    vin, JSONObject.toJSONString(triggeredEventIds));
            return;
        }
        PredictiveEventParamVo paramVo = new PredictiveEventParamVo();
        paramVo.setVinList(Collections.singletonList(vin));
        paramVo.setPredictiveEventInfoVoList(buildClearPredictiveEventList(triggeredEventIds));
        log.info("request clear predictive event sync by vin:{}", JSONObject.toJSONString(paramVo));
        dflzApiFeign.predictiveEventSync(paramVo);
    }

    @Override
    public void clearPredictiveEventSyncByModelCode(String modelCode, List<Long> triggeredEventIds) {
        if (StringUtils.isBlank(modelCode) || CollectionUtils.isEmpty(triggeredEventIds)) {
            log.warn("clear predictive event sync by modelCode ignored, modelCode:{}, triggeredEventIds:{}",
                    modelCode, JSONObject.toJSONString(triggeredEventIds));
            return;
        }
        List<Integer> modelMatlabIds = vehicleModelMatlabService.queryIdsByModelCodes(Collections.singletonList(modelCode));
        if (CollectionUtils.isEmpty(modelMatlabIds)) {
            log.warn("clear predictive event sync by modelCode ignored, modelMatlabIds is empty. modelCode:{}", modelCode);
            return;
        }
        PredictiveEventParamVo paramVo = new PredictiveEventParamVo();
        paramVo.setModelMatlabIdList(modelMatlabIds);
        paramVo.setPredictiveEventInfoVoList(buildClearPredictiveEventList(triggeredEventIds));
        log.info("request clear predictive event sync by modelCode:{}", JSONObject.toJSONString(paramVo));
        dflzApiFeign.predictiveEventSync(paramVo);
    }

    private List<PredictiveEventInfoVo> buildClearPredictiveEventList(List<Long> triggeredEventIds) {
        List<PredictiveEventInfoVo> clearEventList = Lists.newArrayList();
        if (CollectionUtils.isEmpty(triggeredEventIds)) {
            return clearEventList;
        }
        for (Long triggeredEventId : triggeredEventIds) {
            if (triggeredEventId == null) {
                continue;
            }
            PredictiveEventInfoVo clearEvent = new PredictiveEventInfoVo();
            clearEvent.setPredictiveEventId(triggeredEventId);
            clearEvent.setEventRuleId(null);
            clearEventList.add(clearEvent);
        }
        return clearEventList;
    }

    private List<PredictiveEventInfoVo> getPredictiveEventInfoVoList(List<Long> triggeredEventIds){
        List<PredictiveEventInfoVo> predictiveEventInfoVoList = Lists.newArrayList();
        if (triggeredEventIds == null) {
            return predictiveEventInfoVoList;
        }
        for (Long triggeredEventId : triggeredEventIds){
            //预知事件
            TriggeredEventPo triggeredEventPo = triggeredEventDao.getById(triggeredEventId);
            //事件规则
            TriggeredRulePo rulePo = triggeredRuleService.queryById(triggeredEventPo.getRuleId());

            PredictiveEventInfoVo eventInfoVo = new PredictiveEventInfoVo();
            eventInfoVo.setPredictiveEventId(triggeredEventId);
            eventInfoVo.setEventRuleId(rulePo.getId());

            //获取逻辑节点
            List<TriggeredEventRuleVo> eventRuleVoList = triggeredEventRuleService.getEventRuleByRuleId(triggeredEventId, rulePo.getId());
            Integer logicTreeNodeCount = 0;
            List<LogicTreeNodeInfoVo> logicTreeNodeInfoVoList = Lists.newArrayList();
            Integer comparisonSubexpressionCount = 0;
            List<ComparisonSubexpressionInfoVo> comparisonSubexpressionInfoVoList = Lists.newArrayList();
            for (TriggeredEventRuleVo eventRuleVo : eventRuleVoList){
                Integer nodeType = Integer.valueOf(eventRuleVo.getNodeName());
                logicTreeNodeCount ++;
                LogicTreeNodeInfoVo logicTreeNodeInfoVo = new LogicTreeNodeInfoVo();
                String nodeId = eventRuleVo.getNodeId();
                logicTreeNodeInfoVo.setNodeIndex(Integer.valueOf(nodeId));
                String parentId = eventRuleVo.getParentId();
                if(StringUtils.isNotBlank(parentId)){
                    logicTreeNodeInfoVo.setParentNodeIndex(Integer.valueOf(parentId));
                }else {
                    logicTreeNodeInfoVo.setParentNodeIndex(0);
                }
                logicTreeNodeInfoVo.setNodeType(nodeType);

                if(nodeType == RuleNode.LOGICAL_NODE.getType()){
                    logicTreeNodeInfoVo.setLogicOperator(LogicOperatorEnum.getValueByName(eventRuleVo.getOperator()));
                    logicTreeNodeInfoVo.setComparisonSubexpressionIndex(0);
                }else  if(nodeType == RuleNode.COMPARE_NODE.getType()){ //比较子式
                    logicTreeNodeInfoVo.setLogicOperator(0);
                    logicTreeNodeInfoVo.setComparisonSubexpressionIndex(Integer.valueOf(nodeId));

                    comparisonSubexpressionCount ++;
                    ComparisonSubexpressionInfoVo comparisonSubexpressionInfoVo = new ComparisonSubexpressionInfoVo();
                    comparisonSubexpressionInfoVo.setComparisonSubexpressionIndex(Integer.valueOf(nodeId));
                    String canSignal = eventRuleVo.getCanSignal();

                        /*DataItemDecodeRulePo dataItemDecodeRulePo = dataItemDecodeRuleService.queryById(canSignal);
                        String[] decoderParams = dataItemDecodeRulePo.getDecoderParamsString().split(",");
                        String canMessageId = decoderParams[0];
                        comparisonSubexpressionInfoVo.setCanMessageIdLength(canMessageId.length());
                        comparisonSubexpressionInfoVo.setCanMessageId(canMessageId);
                        comparisonSubexpressionInfoVo.setCanSignalByteOrder(3);
                        comparisonSubexpressionInfoVo.setCanSignalStartBit(Integer.valueOf(decoderParams[1]));
                        comparisonSubexpressionInfoVo.setCanSignalBitLength(Integer.valueOf(decoderParams[2]));*/

                    DataItemPo dataItemPo = dataItemService.queryCanByCode(canSignal);
                    String canMessageId = dataItemPo.getCanMsgId();
                    comparisonSubexpressionInfoVo.setCanMessageIdLength(canMessageId.length());
                    comparisonSubexpressionInfoVo.setCanMessageId(canMessageId);
                    comparisonSubexpressionInfoVo.setCanSignalByteOrder(dataItemPo.getCanSignalByteOrder());
                    comparisonSubexpressionInfoVo.setCanSignalStartBit(dataItemPo.getCanStartBit());
                    comparisonSubexpressionInfoVo.setCanSignalBitLength(dataItemPo.getCanBitLength());

                    comparisonSubexpressionInfoVo.setComparisonOperator(ComparisonOperatorEnum.getValueByName(eventRuleVo.getComparator()));
                    String constant = eventRuleVo.getConstant();
                    comparisonSubexpressionInfoVo.setConstantLength(constant.length());
                    comparisonSubexpressionInfoVo.setConstant(constant);
                    comparisonSubexpressionInfoVoList.add(comparisonSubexpressionInfoVo);
                }
                logicTreeNodeInfoVoList.add(logicTreeNodeInfoVo);
            }

            eventInfoVo.setLogicTreeNodeCount(logicTreeNodeCount);
            eventInfoVo.setLogicTreeNodeInfoVoList(logicTreeNodeInfoVoList);
            eventInfoVo.setComparisonSubexpressionCount(comparisonSubexpressionCount);
            eventInfoVo.setComparisonSubexpressionInfoVoList(comparisonSubexpressionInfoVoList);
            predictiveEventInfoVoList.add(eventInfoVo);
        }
        return predictiveEventInfoVoList;
    }

    private List<TriggeredEventRuleVo> getCurrentEventRuleVoList(Long triggeredEventId) {
        TriggeredEventPo eventPo = triggeredEventDao.getById(triggeredEventId);
        if (eventPo == null || StringUtils.isBlank(eventPo.getRuleVersion())) {
            log.warn("predictive event current rule version is blank, skip. triggeredEventId:{}", triggeredEventId);
            return Lists.newArrayList();
        }
        String latestVersion = getLatestRuleVersion(eventPo.getRuleVersion());
        if (StringUtils.isBlank(latestVersion)) {
            log.warn("predictive event latest rule version is blank, skip. triggeredEventId:{}, ruleVersion:{}",
                    triggeredEventId, eventPo.getRuleVersion());
            return Lists.newArrayList();
        }
        return triggeredEventRuleService.getEventRuleByEventId(triggeredEventId, latestVersion);
    }

    private String getLatestRuleVersion(String ruleVersion) {
        if (StringUtils.isBlank(ruleVersion)) {
            return null;
        }
        String[] versions = ruleVersion.split(",");
        for (int i = versions.length - 1; i >= 0; i--) {
            String version = versions[i].trim();
            if (StringUtils.isNotBlank(version)) {
                return version;
            }
        }
        return null;
    }

    private Integer resolveLogicOperator(TriggeredEventRuleVo eventRuleVo) {
        Integer logicOperator = LogicOperatorEnum.getValueByName(eventRuleVo.getOperator());
        if (logicOperator == null || logicOperator == 0) {
            log.warn("logical node operator is invalid, default to AND. triggeredEventId:{}, ruleId:{}, nodeId:{}, operator:{}",
                    eventRuleVo.getTriggeredEventId(), eventRuleVo.getRuleId(), eventRuleVo.getNodeId(), eventRuleVo.getOperator());
            return LogicOperatorEnum.AND.getValue();
        }
        return logicOperator;
    }
}

