package com.ne.business.dflq.triggered.enums;

public enum TaskStatus {

    QUEUEING("提交任务"),
    EXECUTING("执行中"),
    FAILED("任务失败"),
    PAUSE("任务暂停"),
    UNKNOWN("未知状态"),
    CANCELED("任务取消"),
    SUCCESS("任务成功");

    private final String displayName;

    TaskStatus(String displayName) {
        this.displayName = displayName;
    }

    public String getDisplayName() {
        return this.displayName;
    }



    // 从DLCStatus转换为TaskStatus的静态方法
    public static TaskStatus valueFromDlcStatus(Long dlcStatus) {
        // 任务状态：0 初始化， 1 执行中， 2 执行成功，3 数据写入中，4 排队中。-1 执行失败，-3 已取消。
        if (dlcStatus == 0L) {
            return QUEUEING;
        } else if (dlcStatus == 1L) {
            return EXECUTING;
        } else if (dlcStatus == 2L) {
            return SUCCESS;
        } else if (dlcStatus == -1L) {
            return FAILED;
        } else if (dlcStatus == -3L) {
            return CANCELED;
        } else {
            return UNKNOWN;
        }
    }
    public static TaskStatus valueFromCosStatus(String cosStatus) {
//        任务状态
//        Submitted：已提交，待执行。
//        Running：执行中。
//        Success：执行成功。
//        Failed：执行失败。
//        Pause：任务暂停，当暂停队列时，待执行的任务会变为暂停状态。
//        Cancel：任务被取消执行。

        switch (cosStatus) {
            case "Submitted":
                return QUEUEING;
            case "Running":
                return EXECUTING;
            case "Success":
                return SUCCESS;
            case "Failed":
                return FAILED;
            case "Pause":
                return PAUSE;
            case "Cancel":
                return CANCELED;
            default:
                return UNKNOWN;
        }
    }
}

