package com.ne.business.dflq.triggered.utils;


import org.apache.commons.compress.utils.Lists;
import org.apache.commons.lang3.StringUtils;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * - @ClassName: CanUtils
 * - @Des: CAN 信号解析类
 * - @Author: xhy
 * - @Date: 2026/3/11 14:59
 **/
public class CanUtils {

    /**
     * 将字符串转换为指定长度的 byte[] 数组
     * @param str 输入字符串
     * @param length 指定长度
     * @return byte[] 固定长度的字节数组
     */
    public static byte[] stringToFixedLengthBytes(String str, int length) {
        byte[] result = new byte[length];
        if (StringUtils.isBlank(str)) {
            return result;  // 返回全 0 的数组
        }

        byte[] strBytes = str.getBytes(StandardCharsets.UTF_8);
        int copyLength = Math.min(strBytes.length, length);
        System.arraycopy(strBytes, 0, result, 0, copyLength);

        return result;
    }

    /**
     * 将字符串转换为指定长度的 List<Integer> 数组
     * @param str 输入字符串
     * @param length 指定长度
     * @return byte[] 固定长度的字节数组
     */
    public static List<Integer> stringToIntegerList(String str, int length) {
        byte[] result = new byte[length];
        if (StringUtils.isBlank(str)) {
            return bytesToList(result);  // 返回全 0 的数组
        }

        byte[] strBytes = str.getBytes(StandardCharsets.UTF_8);
        int copyLength = Math.min(strBytes.length, length);
        System.arraycopy(strBytes, 0, result, 0, copyLength);

        return bytesToList(result);
    }

    /**
     * 将 byte[] 数组转换为 List<Integer>
     * 每个 byte 值转换为 0-255 的整数
     * @param bytes 字节数组
     * @return List<Integer>
     */
    public static List<Integer> bytesToList(byte[] bytes) {
        if (bytes == null || bytes.length == 0) {
            return Lists.newArrayList();
        }

        List<Integer> result = new ArrayList<>();
        for (byte b : bytes) {
            result.add(b & 0xFF);
        }
        return result;
    }

    /**
     * 将 List<Integer> 转换为 byte[] 数组
     * @param list 整数列表（值范围应为 0-255）
     * @return byte[] 字节数组
     */
    public static byte[] listToBytes(List<Integer> list) {
        if (list == null || list.isEmpty()) {
            return new byte[0];
        }

        byte[] bytes = new byte[list.size()];
        for (int i = 0; i < list.size(); i++) {
            bytes[i] = list.get(i).byteValue();
        }
        return bytes;
    }
}

