83	    /**
84	     * 批量生成近 90 天内的随机时间
85	     * @param count 生成的时间数量
86	     * @return 格式化后的时间字符串列表
87	     */
88	    public static List<String> generateRandomTimes(int count) {
89	        List<String> times = new ArrayList<>(count);
90	        Random random = new Random();
91	
92	        LocalDateTime now = LocalDateTime.now();
93	        LocalDateTime ninetyDaysAgo = now.minusDays(90);
94	
95	        for (int i = 0; i < count; i++) {
96	            long randomSeconds = random.nextInt((int) java.time.Duration.between(ninetyDaysAgo, now).getSeconds());
97	            LocalDateTime randomTime = ninetyDaysAgo.plusSeconds(randomSeconds);
98	            times.add(randomTime.format(FORMATTER));
99	        }
100	
101	        return times;
102	    }
103	
104	    /**
105	     * 生成从 90 天前到现在的所有时间点 (按天生成)
106	     * @return 格式化后的时间字符串列表
107	     */
108	    public static List<String> generateDailyTimes(String startDate, String endDate) {
109	        List<String> dates = new ArrayList<>();
110	
111	        if (startDate == null || endDate == null) {
112	            return dates;
113	        }
114	
115	        try {
116	            LocalDate start = LocalDate.parse(startDate, FORMATTER);
117	            LocalDate end = LocalDate.parse(endDate, FORMATTER);
118	
119	            LocalDate current = start;
120	            while (!current.isAfter(end)) {
121	                dates.add(current.format(FORMATTER_DAY));
122	                current = current.plusDays(1);
123	            }
124	        } catch (Exception e) {
125	            e.printStackTrace();
126	        }
127	
128	        return dates;
129	    }
