210	            LocalDateTime endDt = LocalDateTime.parse(endDate, FORMATTER);
211	
212	            // 转换为毫秒级时间戳
213	            long startMillis = startDt.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
214	            long endMillis = endDt.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
215	
216	            // 按指定间隔生成时间戳
217	            for (long current = startMillis; current <= endMillis; current += interval) {
218	                timestamps.add(current);
219	            }
220	
221	            // 确保包含结束时间
222	            if (timestamps.isEmpty() || !timestamps.get(timestamps.size() - 1).equals(endMillis)) {
