package com.ne.business.dflq.triggered.utils;

import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoField;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

/**
 * - @ClassName: DateUtil
 * - @Des:
 * - @Author: xhy
 * - @Date: 2026/3/24 09:08
 **/
public class DateUtils {

    // 90 天的秒数：90 * 24 * 60 * 60 = 259,200 秒
    public static final long DAYS_IN_SECONDS_90 = 90L * 24 * 60 * 60;
    // 30 天的秒数：30 * 24 * 60 * 60 = 2,592,000 秒
    public static final long DAYS_IN_SECONDS_30 = 30L * 24 * 60 * 60;
    // 7 天的秒数：7 * 24 * 60 * 60 = 604,800 秒
    public static final long DAYS_IN_SECONDS_7 = 7L * 24 * 60 * 60;
    // 3 天的秒数：3 * 24 * 60 * 60 = 259,200 秒
    public static final long DAYS_IN_SECONDS_3 = 3L * 24 * 60 * 60;
    // 24 小时的秒数：24 * 60 * 60 = 86,400 秒 *
    public static final long HOURS_IN_SECONDS_24 = 24L * 60 * 60;
    // 12 小时的秒数：12 * 60 * 60 = 43,200 秒 *
    public static final long HOURS_IN_SECONDS_12 = 12L * 60 * 60;
    // 3 小时的秒数：12 * 60 * 60 = 43,200 秒 *
    public static final long HOURS_IN_SECONDS_3 = 3L * 60 * 60;
    // 6 小时的秒数：6 * 60 * 60 = 21,600 秒
    public static final long HOURS_IN_SECONDS_6 = 6L * 60 * 60;
    // 1 小时的秒数：1 * 60 * 60 = 3,600 秒
    public static final long HOURS_IN_SECONDS_1 = 1L * 60 * 60;
    // 30 分钟的秒数：30 * 60 = 1,800 秒
    public static final long MINUTES_IN_SECONDS_30 = 30L * 60;
    // 15 分钟的秒数：15 * 60 = 900 秒
    public static final long MINUTES_IN_SECONDS_15 = 15L * 60;
    // 10 分钟的秒数：10 * 60 = 600 秒
    public static final long MINUTES_IN_SECONDS_10 = 10L * 60;
    // 5 分钟的秒数：5 * 60 = 300 秒
    public static final long MINUTES_IN_SECONDS_5 = 5L * 60;
    // 3 分钟的秒数：3 * 60 = 180 秒
    public static final long MINUTES_IN_SECONDS_3 = 3L * 60;
    // 1 分钟的秒数：3 * 60 = 180 秒
    public static final long MINUTES_IN_SECONDS_1 = 1L * 60;

    //30秒
    public static final long SECONDS_30 = 30L;
    // 15 秒
    public static final long SECONDS_15 = 15L;
    //10秒
    public static final long SECONDS_10 = 10L;
    //5秒
    public static final long SECONDS_5 = 5L;
    //1秒
    public static final long SECONDS_1 = 1L;
    // 100毫秒
    public static final long MILLISECONDS_100 = 100L;

    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    private static final DateTimeFormatter FORMATTER_S = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.S");

    private static final DateTimeFormatter FORMATTER_DAY = DateTimeFormatter.ofPattern("yyyy-MM-dd");

    private static final DateTimeFormatter FORMATTER_HOUR = DateTimeFormatter.ofPattern("MM-dd HH:00");

    private static final DateTimeFormatter FORMATTER_HOUR_HH = DateTimeFormatter.ofPattern("HH:00");

    private static final DateTimeFormatter FORMATTER_MINUTE = DateTimeFormatter.ofPattern("HH:mm");

    private static final DateTimeFormatter FORMATTER_TIME = DateTimeFormatter.ofPattern("HH:mm:ss");

    private static final DateTimeFormatter FORMATTER_SECONDS = DateTimeFormatter.ofPattern("mm:ss");

    private static final DateTimeFormatter FORMATTER_TIME_S = DateTimeFormatter.ofPattern("HH:mm:ss.S");
    /**
     * 批量生成近 90 天内的随机时间
     * @param count 生成的时间数量
     * @return 格式化后的时间字符串列表
     */
    public static List<String> generateRandomTimes(int count) {
        List<String> times = new ArrayList<>(count);
        Random random = new Random();

        LocalDateTime now = LocalDateTime.now();
        LocalDateTime ninetyDaysAgo = now.minusDays(90);

        for (int i = 0; i < count; i++) {
            long randomSeconds = random.nextInt((int) java.time.Duration.between(ninetyDaysAgo, now).getSeconds());
            LocalDateTime randomTime = ninetyDaysAgo.plusSeconds(randomSeconds);
            times.add(randomTime.format(FORMATTER));
        }

        return times;
    }

    /**
     * 生成从 90 天前到现在的所有时间点 (按天生成)
     * @return 格式化后的时间字符串列表
     */
    public static List<String> generateDailyTimes(String startDate, String endDate) {
        List<String> dates = new ArrayList<>();

        if (startDate == null || endDate == null) {
            return dates;
        }

        try {
            LocalDate start = LocalDate.parse(startDate, FORMATTER);
            LocalDate end = LocalDate.parse(endDate, FORMATTER);

            LocalDate current = start;
            while (!current.isAfter(end)) {
                dates.add(current.format(FORMATTER_DAY));
                current = current.plusDays(1);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return dates;
    }

    public static List<String> generateHoursTimes(String startDate, String endDate, int intervalHours) {
        List<String> dates = new ArrayList<>();

        if (startDate == null || endDate == null) {
            return dates;
        }

        try {
            LocalDateTime start = LocalDateTime.parse(startDate, FORMATTER);
            LocalDateTime end = LocalDateTime.parse(endDate, FORMATTER);

            LocalDateTime current = start;
            while (!current.isAfter(end)) {
                dates.add(current.format(FORMATTER));
                current = current.plusHours(intervalHours);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return dates;
    }

    public static List<String> generateMinuteTimes(String startDate, String endDate, int intervalHours) {
        List<String> dates = new ArrayList<>();

        if (startDate == null || endDate == null) {
            return dates;
        }

        try {
            LocalDateTime start = LocalDateTime.parse(startDate, FORMATTER);
            LocalDateTime end = LocalDateTime.parse(endDate, FORMATTER);

            LocalDateTime current = start;
            while (!current.isAfter(end)) {
                dates.add(current.format(FORMATTER));
                current = current.plusMinutes(intervalHours);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return dates;
    }

    public static List<String> generateSecondTimes(String startDate, String endDate, long interval) {
        List<String> dates = new ArrayList<>();

        if (startDate == null || endDate == null) {
            return dates;
        }

        try {
            LocalDateTime start = LocalDateTime.parse(startDate, FORMATTER);
            LocalDateTime end = LocalDateTime.parse(endDate, FORMATTER);

            LocalDateTime current = end;
            while (!current.isBefore(start)) {
                dates.add(current.format(FORMATTER));
                current = current.minusSeconds(interval);
            }
            dates.add(current.format(FORMATTER));
            Collections.reverse(dates);
        } catch (Exception e) {
            e.printStackTrace();
        }

        return dates;
    }

    public static List<Long> generateMillisecondTimes(String startDate, String endDate, long interval) {
        List<Long> timestamps = new ArrayList<>();

        if (startDate == null || endDate == null) {
            return timestamps;
        }
        try {
            LocalDateTime startDt = LocalDateTime.parse(startDate, FORMATTER);
            LocalDateTime endDt = LocalDateTime.parse(endDate, FORMATTER);

            // 转换为毫秒级时间戳
            long startMillis = startDt.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
            long endMillis = endDt.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();

            // 按指定间隔生成时间戳
            for (long current = startMillis; current <= endMillis; current += interval) {
                timestamps.add(current);
            }

            // 确保包含结束时间
            if (timestamps.isEmpty() || !timestamps.get(timestamps.size() - 1).equals(endMillis)) {
                timestamps.add(endMillis);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return timestamps;
    }

    /**
     * 生成指定天前的具体时间
     * @param daysAgo 多少天前
     * @param hour 小时 (0-23)
     * @param minute 分钟 (0-59)
     * @param second 秒 (0-59)
     * @return 格式化后的时间字符串
     */
    public static String generateSpecificTime(int daysAgo, int hour, int minute, int second) {
        LocalDateTime time = LocalDateTime.now().minusDays(daysAgo)
                .withHour(hour)
                .withMinute(minute)
                .withSecond(second);
        return time.format(FORMATTER);
    }

    /**
     * 打印生成的时间列表
     * @param times 时间列表
     */
    public static void printTimes(List<String> times) {
        times.forEach(System.out::println);
    }


    public static String getCurrentTime() {
        LocalDateTime now = LocalDateTime.now();
        return now.format(FORMATTER);
    }

    /**
     * 获取当前时间减少 N 天的时间
     * @param days 减少的天数
     * @return 格式化后的时间字符串 (yyyy-MM-dd HH:mm:ss)
     */
    public static String getPastTime(int days) {
        LocalDateTime pastTime = LocalDateTime.now().minusDays(days).withHour(0).withMinute(0).withSecond(0).withNano(0);
        return pastTime.format(FORMATTER);
    }

    /**
     * 获取指定日期的开始时间（当天最小时间 00:00:00）
     * @param date 日期字符串 (格式：yyyy-MM-dd)
     * @return 格式化后的时间字符串 (yyyy-MM-dd 00:00:00)
     */
    public static String getDayStartTime(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDate localDate = LocalDate.parse(date, FORMATTER_DAY);
            LocalDateTime startOfDay = localDate.atStartOfDay();
            return startOfDay.format(FORMATTER);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getDayTime(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDateTime localDate = LocalDateTime.parse(date, FORMATTER);
            return localDate.format(FORMATTER_DAY);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
    public static String getHourTime(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDateTime localDate = LocalDateTime.parse(date, FORMATTER);
            return localDate.format(FORMATTER_HOUR);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getHourTimeH(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDateTime localDate = LocalDateTime.parse(date, FORMATTER);
            return localDate.format(FORMATTER_HOUR_HH);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getMinuteTime(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDateTime localDate = LocalDateTime.parse(date, FORMATTER);
            return localDate.format(FORMATTER_MINUTE);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getSecondsTime(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDateTime localDate = LocalDateTime.parse(date, FORMATTER);
            return localDate.format(FORMATTER_SECONDS);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getFormatTime(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDateTime localDate = LocalDateTime.parse(date, FORMATTER);
            return localDate.format(FORMATTER_TIME);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String getFormatTimeS(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDateTime localDate = LocalDateTime.parse(date, FORMATTER);
            return localDate.format(FORMATTER_TIME_S);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static boolean isTimeInterval(String time, String startTime, String endTime) {
        try {
            LocalDateTime timeDt = LocalDateTime.parse(time, FORMATTER_S);
            LocalDateTime startDt = LocalDateTime.parse(startTime, FORMATTER);
            LocalDateTime endDt = LocalDateTime.parse(endTime, FORMATTER);

            // 判断：time >= startTime && time < endTime
            return (timeDt.isEqual(startDt) || timeDt.isAfter(startDt))
                    && timeDt.isBefore(endDt);
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    public static boolean isTimeInterval(Long time, Long startTime, Long endTime) {
        try {
            // 判断：time >= startTime && time < endTime
            return (time >= startTime && time < endTime);
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    /**
     * 获取指定日期的结束时间（当天最大时间 23:59:59）
     * @param date 日期字符串 (格式：yyyy-MM-dd)
     * @return 格式化后的时间字符串 (yyyy-MM-dd 23:59:59)
     */
    public static String getDayEndTime(String date) {
        if (date == null || date.trim().isEmpty()) {
            return null;
        }
        try {
            LocalDate localDate = LocalDate.parse(date, FORMATTER_DAY);
            LocalDateTime endOfDay = localDate.atTime(23, 59, 59);
            return endOfDay.format(FORMATTER);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static Long getTimeDifference(String startTime, String endTime) {
        try {
            LocalDateTime start = LocalDateTime.parse(startTime, FORMATTER);
            LocalDateTime end = LocalDateTime.parse(endTime, FORMATTER);
            return java.time.Duration.between(start, end).getSeconds();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static String timestampToTime(Long timestamp) {
        if (timestamp == null) {
            return null;
        }
        try {
            Instant instant = Instant.ofEpochMilli(timestamp);
            LocalDateTime dateTime = LocalDateTime.ofInstant(instant, ZoneId.systemDefault());
            return dateTime.format(DateTimeFormatter.ofPattern("mm:ss.SSS"));
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    /**
     * 将毫秒时间戳转换为日期格式 (yyyy-MM-dd)
     * @param timestamp 毫秒时间戳
     * @return 格式化后的日期字符串 (yyyy-MM-dd)
     */
    public static String timestampToDate(String timestamp) {
        if (timestamp == null || timestamp.trim().isEmpty()) {
            return null;
        }
        try {
            Long millis = Long.parseLong(timestamp);
            Instant instant = Instant.ofEpochMilli(millis);
            LocalDate date = LocalDateTime.ofInstant(instant, ZoneId.systemDefault()).toLocalDate();
            return date.format(FORMATTER_DAY);
        } catch (Exception e) {
