80	                    outputStream.write(buffer, 0, length);
81	                }
82	                outputStream.flush();
83	            }
84	        } catch (Exception e) {
85	            log.error("通过预签名地址下载 COS 文件异常: bucket={}, key={}",
86	                    cosConfig.getDpBucket(), cosKey, e);
87	            if (!response.isCommitted()) {
88	                response.reset();
89	                response.sendError(HttpServletResponse.SC_BAD_GATEWAY, "从腾讯云获取文件失败");
90	            }
91	        } finally {
92	            if (connection != null) {
93	                connection.disconnect();
94	            }
95	        }
