98	    private boolean isValidFileName(String fileName) {
99	        return StringUtils.hasText(fileName)
100	                && !fileName.contains("/")
101	                && !fileName.contains("\\")
102	                && !fileName.contains("\r")
103	                && !fileName.contains("\n");
