public class TestController {

    private static final int BUFFER_SIZE = 8192;

    private final TencentCosConfig cosConfig;
    private final TencentCosService tencentCosService;

    // TODO 文件下载接口，开放给 T 盒联调使用，项目正式上线后需要删除
    @GetMapping(path = "/getFile")
    public void getFile(@RequestParam String fileName, HttpServletResponse response) throws IOException {
        if (!isValidFileName(fileName)) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "fileName 参数不合法");
            return;
        }

        String cosKey = cosConfig.getPrefix() + fileName;
        log.info("通过预签名地址下载 COS 文件: bucket={}, key={}", cosConfig.getDpBucket(), cosKey);

        HttpURLConnection connection = null;
        try {
            URL presignedUrl = tencentCosService.generatePresignedDownloadUrl(cosConfig.getDpBucket(), cosKey);
            connection = (HttpURLConnection) presignedUrl.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(cosConfig.getConnectionTimeout());
            connection.setReadTimeout(cosConfig.getSocketTimeout());

            int statusCode = connection.getResponseCode();
            if (statusCode < HttpServletResponse.SC_OK || statusCode >= HttpServletResponse.SC_MULTIPLE_CHOICES) {
                int responseStatus = statusCode == HttpServletResponse.SC_NOT_FOUND
                        ? HttpServletResponse.SC_NOT_FOUND
                        : HttpServletResponse.SC_BAD_GATEWAY;
                log.error("从 COS 下载文件失败: bucket={}, key={}, status={}",
                        cosConfig.getDpBucket(), cosKey, statusCode);
                response.sendError(responseStatus, "从腾讯云获取文件失败");
                return;
            }

            response.setStatus(HttpServletResponse.SC_OK);
            response.setContentType("application/octet-stream");
            response.setCharacterEncoding("UTF-8");
            response.setHeader("Content-Disposition", "attachment; filename*=UTF-8''" + encodeFileName(fileName));
            long contentLength = connection.getContentLengthLong();
            if (contentLength >= 0) {
                response.setContentLengthLong(contentLength);
            }

            try (InputStream inputStream = connection.getInputStream();
                 ServletOutputStream outputStream = response.getOutputStream()) {
                byte[] buffer = new byte[BUFFER_SIZE];
                int length;
                while ((length = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, length);
                }
                outputStream.flush();
            }
        } catch (Exception e) {
            log.error("通过预签名地址下载 COS 文件异常: bucket={}, key={}",
                    cosConfig.getDpBucket(), cosKey, e);
            if (!response.isCommitted()) {
                response.reset();
                response.sendError(HttpServletResponse.SC_BAD_GATEWAY, "从腾讯云获取文件失败");
            }
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private boolean isValidFileName(String fileName) {
        return StringUtils.hasText(fileName)
                && !fileName.contains("/")
                && !fileName.contains("\\")
                && !fileName.contains("\r")
                && !fileName.contains("\n");
    }

    private String encodeFileName(String fileName) throws IOException {
        return URLEncoder.encode(fileName, "UTF-8").replace("+", "%20");
    }
}

