package com.ne.business.dflq.triggered.error;

import com.ne.boot.common.exception.IError;


public enum VehicleError implements IError {
    /**
     * 车辆不存在
     */
    VEHICLE_FILE_FOUND("0005", "上传文件错误"),
    VEHICLE_NOT_FOUND("0001", "车辆不存在"),
    VEHICLE_IMPORT_PARAM_ERROR("0006", "导入参数错误"),
    VEHICLE_TRIGGERED_EVENT_IDS_LIMIT("0007", "预知事件ID数量不能超过5个"),
    VEHICLE_TRIGGERED_EVENT_IDS_EXCEED_LIMIT("0008", "该车型已关联的预知事件ID数量超过5个，无法继续添加"),
    VEHICLE_VIN_TRIGGERED_EVENT_IDS_LIMIT("0009", "预知事件ID数量不能超过10个"),
    VEHICLE_VIN_TRIGGERED_EVENT_IDS_EXCEED_LIMIT("0010", "该车辆已关联的预知事件ID数量超过10个，无法继续添加");

    String errorCode;
    String errorMessage;
    private static final String ns = "VEHICLE";

    VehicleError(String errorCode, String errorMessage) {
        this.errorCode = errorCode;
        this.errorMessage = errorMessage;
    }

    public String getNamespace() {
        return ns;
    }

    public String getErrorCode() {
        return ns + "_" + errorCode;
    }

    public String getErrorMessage() {
        return errorMessage;
    }

    public void setErrorMessage(String msg) {
        this.errorMessage = msg;
    }
}

