import org.springframework.stereotype.Component;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

/**
 * - @ClassName: TencentDlcConfig
 * - @Des: DLC
 * - @Author: xhy
 * - @Date: 2026/3/12 15:34
 **/
@Component
@Data
@Configuration
public class TencentDlcConfig {

    @Value("${dlc.endpoint}")
    private String endpoint;
    @Value("${dlc.secretId}")
    private String secretId;
    @Value("${dlc.secretKey}")
    private String secretKey;
    @Value("${dlc.taskType}")
    private String taskType;
    @Value("${dlc.databaseName}")
    private String databaseName;
    @Value("${dlc.datasourceConnectionName}")
    private String datasourceConnectionName;
    @Value("${dlc.region}")
    private String region;
    @Value("${dlc.dataEngineName}")
    private String dataEngineName;
    @Value("${dlc.cloudUid}")
    private String cloudUid;
    @Value("${dlc.cosBucketName}")
    private String cosBucketName;
    @Value("${dlc.callbackUrl}")
    private String callbackUrl;
    @Value("${dlc.reqDownloadOriginalToCosUrl}")
    private String reqDownloadOriginalToCosUrl;
    @Value("${dlc.socketTimeout}")
    private String socketTimeout;

    @Bean
    public Connection dclConnection() throws SQLException {
        String url = String.format("jdbc:dlc:%s?task_type=%s&database_name=%s&datasource_connection_name=%s&region=%s&data_engine_name=%s&socketTimeout=%s",
                endpoint, taskType, databaseName, datasourceConnectionName, region, dataEngineName, socketTimeout);
        return DriverManager.getConnection(url, secretId, secretKey);
    }

}

