import lombok.extern.slf4j.Slf4j;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.compress.utils.Lists;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.Arrays;
import java.util.Date;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * - @ClassName: TriggeredCanViewServiceImpl
 * - @Des:
 * - @Author: xhy
 * - @Date: 2026/3/16 14:33
 **/
@Slf4j
@Service
public class TriggeredCanViewServiceImpl implements TriggeredCanViewService {

    @Autowired
    TriggeredCanViewDao triggeredCanViewDao;
    @Autowired
    DataItemService dataItemService;
    @Autowired
    TriggeredRecordDao triggeredRecordDao;
    @Autowired
    DlcQueryService dlcQueryService;

    @Override
    public Response insert(TriggeredCanViewDTO dto) {
        TriggeredCanViewPo viewPo = new TriggeredCanViewPo();
        viewPo.setRecordId(dto.getRecordId());
        viewPo.setName(dto.getName());
        viewPo.setCreateTime(new Date());
        viewPo.setUpdateTime(new Date());
        viewPo.setCanCode(StringUtils.join(dto.getCanCodeList(), ","));
        viewPo.setUserId(dto.getUserId());
        viewPo.setUserName(dto.getUserName());
        viewPo.setCanPlatform(dto.getCanPlatform());
        triggeredCanViewDao.insert(viewPo);
        return Response.success();
    }

    @Override
    public Response querySelectList(TriggeredCanViewDTO dto) {
        List<TriggeredCanViewPo> list = triggeredCanViewDao.querySelectList(dto);

        return Response.success(list);
    }

    @Override
    public Response update(TriggeredCanViewDTO dto) {
        TriggeredCanViewPo viewPo = new TriggeredCanViewPo();
        viewPo.setId(dto.getId());
        viewPo.setName(dto.getName());
        viewPo.setUpdateTime(new Date());
        if(CollectionUtils.isNotEmpty(dto.getCanCodeList())){
            viewPo.setCanCode(StringUtils.join(dto.getCanCodeList(), ","));
        }
        triggeredCanViewDao.update(viewPo);
        return Response.success();
    }

    @Override
    public Response deleteById(Integer id) {
        triggeredCanViewDao.deleteById(id);
        return Response.success();
    }

    @Override
    public Response getCanCodeList(Integer id) {
        TriggeredCanViewPo viewPo = triggeredCanViewDao.queryById(id);
        TriggeredRecordVo recordVo = triggeredRecordDao.queryTriggeredRecordInfo(viewPo.getRecordId());
        List<String> list = Arrays.asList(StringUtils.split(viewPo.getCanCode(), ","));
        List<CanMessageVo> canMessageVos = dataItemService.queryCanListByCanCodes( list, recordVo.getCanPlatform());
        return Response.success(canMessageVos);
    }

    @Override
    public Response getSignalTrend(SignalTrendDTO dto) {
        TriggeredRecordPo recordPo = triggeredRecordDao.queryById(dto.getId());
        SignalTrendVo signalTrendVo = new SignalTrendVo();
        List<CanMessageVo> canMessageVos = dataItemService.queryCanListByCanCodes( dto.getCanCodeList(), dto.getCanPlatform());
        signalTrendVo.setCanSignal(canMessageVos);

        // 预先构建 code 到 CanMessageVo 的映射，避免内层循环查找
        Map<String, CanMessageVo> codeToVoMap = canMessageVos.stream()
            .collect(Collectors.toMap(CanMessageVo::getCode, vo -> vo));

        List<Map<String, Object>> valueList = Lists.newArrayList();
        String tableName = recordPo.getOriginalFileName();

        // 将时间戳转换为日期格式用于 dt查询
        String startDt = DateUtils.timestampToDate(dto.getStartTime());
        String endDt = DateUtils.timestampToDate(dto.getEndTime());
        // 只查询需要的列，避免 SELECT * 提升查询性能；同时增加 dt条件进行分区裁剪
        String sql = "SELECT * FROM " + "`" + tableName + "`" + " WHERE vin = ? AND time >= ? AND time <= ? AND dt >= ? AND dt <= ? ORDER BY time ASC";
        List<Map<String, Object>> list = dlcQueryService.executeQueryWithParams(sql, dto.getVin(), dto.getStartTime(), dto.getEndTime(), startDt, endDt);
        for (Map<String, Object> map : list){
            Map<String, Object> item = Maps.newConcurrentMap();
            String time = (String) map.get("time");
            Map<String, Object> valueMap = JSONObject.parseObject((String) map.get("decoded_data"));

            // 直接遍历 valueMap 的 key，而不是遍历 507 个信号
            for (Map.Entry<String, Object> entry : valueMap.entrySet()) {
                String code = entry.getKey();
                if (codeToVoMap.containsKey(code)) {
                    String value = (String) entry.getValue();
                    if(StringUtils.isNotBlank(value)){
                        item.put(code, value);
                    }
                }
            }
            item.put("time", time);
            valueList.add(item);
        }

        signalTrendVo.setValue(valueList);
        return Response.success(signalTrendVo);
    }
}

