231	    /**
232	     * 将解码规则 JSON 上传到 COS
233	     * 参考 status-common-service 的 SparkTaskHandlerService.dataRuleJsonToCos()
234	     *
235	     * @param rules 解码规则列表
236	     * @param cosKey COS 文件路径
237	     */
238	    private void dataRuleJsonToCos(List<DataItemDecodeRulePo> rules, String cosKey) {
239	        try {
240	            // 转换数据格式：comparisonFieldName → displayName，新增 tagId 和 decoderParameters
241	            // 只处理前缀为 MIX_CUSTOM_0X81 的规则
242	            List<Map<String, Object>> transformedList = new ArrayList<>();
243	            for (DataItemDecodeRulePo rule : rules) {
244	                if (!rule.getDataItemCode().startsWith("MIX_CUSTOM_0X81")) {
245	                    continue;
246	                }
247	                Map<String, Object> item = new LinkedHashMap<>();
248	                item.put("dataItemCode", rule.getDataItemCode());
249	                item.put("decoderName", rule.getDecoderName());
250	                item.put("decoderParameters", null);
251	                item.put("tagId", "12");
252	                item.put("decoderParamsString", rule.getDecoderParamsString());
253	                item.put("displayName", rule.getComparisonFieldName());
254	                transformedList.add(item);
255	            }
256	            // 按 tagId 分组，key 固定为 "12"
257	            Map<String, List<Map<String, Object>>> result = new LinkedHashMap<>();
258	            result.put("12", transformedList);
259	
260	            File jsonFile = File.createTempFile("decode-rule-triggered", ".json");
261	            ObjectMapper objectMapper = new ObjectMapper();
262	            objectMapper.enable(SerializationFeature.INDENT_OUTPUT);
263	            objectMapper.writeValue(jsonFile, result);
264	            boolean success = tencentCosService.putFile(cosKey, java.nio.file.Files.readAllBytes(jsonFile.toPath()));
265	            if (!success) {
266	                throw new RuntimeException("上传解码规则文件到 COS 失败");
267	            }
268	            log.info("解码规则文件已上传到 COS：{}", cosKey);
269	            // 清理临时文件
270	            if (jsonFile.exists()) {
271	                jsonFile.delete();
272	            }
273	        } catch (Exception e) {
274	            log.error("上传解码规则文件到 COS 失败", e);
275	            throw new RuntimeException("上传解码规则文件到 COS 失败", e);
276	        }
277	    }
