280	    public Response startAnalysisTask(TriggeredRecordDTO triggeredRecord) {
281	
282	        TriggeredRecordPo recordPo = triggeredRecordDao.queryById(triggeredRecord.getId());
283	
284	        // 创建解析任务
285	        AnalysisTask task = new AnalysisTask();
286	        Map<String, String> exportParams = new HashMap<>();
287	        // fileName需要带后缀
288	        exportParams.put("fileName", recordPo.getOriginalFileName() + tencentCosConfig.getSuffix());
289	        exportParams.put("cosUrl", tencentCosConfig.getCosUrl());
290	        exportParams.put("bucketName", tencentCosConfig.getDpBucket());
291	        exportParams.put("decodeRuleFileName", recordPo.getRuleFileName());
292	        exportParams.put("vin", recordPo.getVin());
293	        exportParams.put("tableName", tencentDlcConfig.getDatabaseName()+"." + recordPo.getOriginalFileName());
294	        task.setExportParams(exportParams);
295	        log.info("AnalysisTask:{}", JsonUtil.writeValueAsPrettyString(task));
296	        dlcService.createSparkAppTask(task);
297	
298	        // 启动解析任务后，设置清除时间为当前时间 + 7 天，并重置数据删除标记
299	        Date clearTime = new Date(System.currentTimeMillis() + 7L * 24 * 60 * 60 * 1000);
300	        recordPo.setClearTime(clearTime);
301	        recordPo.setDataIsDelete(0);
302	        triggeredRecordDao.update(recordPo);
303	        log.info("已设置清除时间并重置data_is_delete=0，记录ID: {}, 清除时间: {}", recordPo.getId(), clearTime);
304	
305	        // 保存解析任务记录
306	        TriggeredRecordTaskPo taskPo = new TriggeredRecordTaskPo();
307	        taskPo.setRecordId(recordPo.getId());
308	        taskPo.setTaskId(task.getSparkTaskId());
309	        if (StringUtils.isNotBlank(task.getSparkTaskId())) {
310	            taskPo.setTaskState(1);
311	        }else {
312	            taskPo.setTaskState(0);
313	        }
314	        taskPo.setCreateTime(new Date());
315	        taskPo.setUpdateTime(new Date());
316	        triggeredRecordTaskDao.insert(taskPo);
317	
318	        // 启动新线程定时查询解析状态
319	        if (StringUtils.isNotBlank(task.getSparkTaskId())) {
320	            startTaskStatusMonitor(taskPo.getId(), task, triggeredRecord.getId());
321	        }
322	
323	        return Response.success();
324	    }
