326	    /**
327	     * 启动任务状态监控线程
328	     * @param taskPoId 任务记录 ID
329	     * @param analysisTask 分析任务对象
330	     * @param recordId 触发记录 ID
331	     */
332	    private void startTaskStatusMonitor(Integer taskPoId, AnalysisTask analysisTask, Long recordId) {
333	        CompletableFuture.runAsync(() -> {
334	            try {
335	                log.info("开始监控任务状态，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());
336	
337	                int maxRetryCount = 60; // 最多查询 60 次（约 1 小时，每次间隔 60秒）
338	                int retryCount = 0;
339	
340	                while (retryCount < maxRetryCount) {
341	                    TimeUnit.SECONDS.sleep(60);
342	
343	                    AnalysisTask updatedTask = dlcService.describeTasks(analysisTask);
344	                    TaskStatus currentStatus = updatedTask.getStatus();
345	
346	                    if (currentStatus == null) {
347	                        log.warn("任务状态为空，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());
348	                        currentStatus = TaskStatus.UNKNOWN;
349	                    }
350	
351	                    log.info("任务状态更新 - 任务记录 ID: {}, Spark 任务 ID: {}, 当前状态：{}",
352	                            taskPoId, analysisTask.getSparkTaskId(), currentStatus.getDisplayName());
353	
354	                    TriggeredRecordTaskPo taskPo = triggeredRecordTaskDao.queryById(taskPoId.longValue());
355	                    if (taskPo != null) {
356	                        //taskPo.setTaskStatus(currentStatus.name());
357	
358	                        if (currentStatus == TaskStatus.SUCCESS) {
359	                            taskPo.setTaskState(2);
360	                            taskPo.setUpdateTime(new Date());
361	                            triggeredRecordTaskDao.update(taskPo);
362	                            // 更新原记录的解析状态为已解析
363	                            TriggeredRecordPo recordPo = triggeredRecordDao.queryById(recordId);
364	                            if (recordPo != null) {
365	                                recordPo.setAnalysisStatus(1);
366	                                triggeredRecordDao.update(recordPo);
367	                                log.info("已更新原记录解析状态为已解析，记录 ID: {}", taskPo.getRecordId());
368	                            }
369	                            //更新任务记录的状态为已解析
370	                            List<TriggeredRecordTaskPo> taskPoList = triggeredRecordTaskDao.queryTaskListByRecordId(recordId);
371	                            //查找最早时间的数据
372	                            TriggeredRecordTaskPo earliestTask = taskPoList.stream()
373	                                    .filter(t -> t.getCreateTime() != null)
374	                                    .min(Comparator.comparing(TriggeredRecordTaskPo::getCreateTime))
375	                                    .orElse(null);
376	                            if (earliestTask != null) {
377	                                earliestTask.setTaskState(2);
378	                                earliestTask.setUpdateTime(new Date());
379	                                triggeredRecordTaskDao.update(earliestTask);
380	                                log.info("已更新最早任务记录为已解析，任务记录 ID: {}, 创建时间: {}", earliestTask.getId(), earliestTask.getCreateTime());
381	                            }
382	
383	                            log.info("任务执行成功，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());
384	                            break;
385	                        } else if (currentStatus == TaskStatus.FAILED ||
386	                                currentStatus == TaskStatus.CANCELED) {
387	                            taskPo.setTaskState(-1);
388	                            taskPo.setUpdateTime(new Date());
389	                            triggeredRecordTaskDao.update(taskPo);
390	                            log.error("任务执行失败，任务记录 ID: {}, Spark 任务 ID: {}, 状态：{}",
391	                                    taskPoId, analysisTask.getSparkTaskId(), currentStatus.getDisplayName());
392	                            break;
393	                        }
394	                    }
395	
396	                    retryCount++;
397	                }
398	
399	                if (retryCount >= maxRetryCount) {
400	                    log.warn("任务监控超时，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());
401	                    TriggeredRecordTaskPo taskPo = triggeredRecordTaskDao.queryById(taskPoId.longValue());
402	                    if (taskPo != null) {
403	                        taskPo.setTaskState(-1);
404	                       // taskPo.setTaskStatus(TaskStatus.GET_EXPORT_STATUS_FAILED.name());
405	                        triggeredRecordTaskDao.update(taskPo);
406	                    }
407	                }
408	
409	            } catch (Exception e) {
410	                log.error("任务状态监控异常，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId(), e);
411	                try {
412	                    TriggeredRecordTaskPo taskPo = triggeredRecordTaskDao.queryById(taskPoId.longValue());
413	                    if (taskPo != null) {
414	                        taskPo.setTaskState(-1);
415	                        taskPo.setUpdateTime(new Date());
416	                        //taskPo.setTaskStatus(TaskStatus.GET_EXPORT_STATUS_FAILED.name());
417	                        triggeredRecordTaskDao.update(taskPo);
418	                    }
419	                } catch (Exception ex) {
420	                    log.error("更新失败状态时出错，任务记录 ID: {}", taskPoId, ex);
421	                }
422	            }
423	        });
424	    }
