/**
 * 管理触发记录表;(TRIGGERED_RECORD)表服务接口实现类
 * @author : xhy
 * @date : 2026-2-26
 */
@Slf4j
@Service
public class TriggeredRecordServiceImpl implements TriggeredRecordService {
    @Autowired
    private TriggeredRecordDao triggeredRecordDao;

    @Autowired
    TriggeredRecordTaskDao triggeredRecordTaskDao;

    @Autowired
    private DlcService dlcService;

    @Autowired
    private DlcQueryService dlcQueryService;

    @Autowired
    TencentDlcConfig tencentDlcConfig;
    @Autowired
    TencentCosConfig tencentCosConfig;

    @Autowired
    TencentCosService tencentCosService;

    @Autowired
    DataItemDecodeRuleService dataItemDecodeRuleService;

    /**
     * 通过ID查询单条数据
     *
     * @param id 主键
     * @return 实例对象
     */
    public Response getInfo(Long id){
        TriggeredRecordVo recordVo = triggeredRecordDao.queryTriggeredRecordInfo(id);
        List<TriggeredRecordTaskPo> triggeredRecordTaskList = triggeredRecordTaskDao.queryTaskListByRecordId(id);
        recordVo.setTriggeredRecordTaskList(triggeredRecordTaskList);
        return Response.success(recordVo);
    }

    /**
     * 分页查询
     *
     * @param query 筛选条件
     * @return 查询结果
     */
    @Override
    public Response paginQuery(TriggeredEventQuery query) {
        Long pageNum = query.getPageIndex();
        Long pageSize = query.getPageSize();
        query.setOffset((pageNum - 1) * pageSize);
        Long count = triggeredRecordDao.count(query);
        List<TriggeredRecordVo> list = triggeredRecordDao.queryListByLimit(query);
        Page page = new Page();
        page.setPageIndex(query.getPageIndex());
        page.setPageSize(query.getPageSize());
        page.setTotalCount(count);
        return Response.success(list, page);
    }

    /**
     * 新增数据
     *
     * @param triggeredRecord 实例对象
     * @return 实例对象
     */
    public Response insert(TriggeredRecordDTO triggeredRecord){
        TriggeredRecordPo triggeredRecordPo = new TriggeredRecordPo();
        BeanUtils.copyProperties(triggeredRecord, triggeredRecordPo);
        // 新数据默认未解析状态
        if (triggeredRecordPo.getAnalysisStatus() == null) {
            triggeredRecordPo.setAnalysisStatus(0);
        }

        // BeanUtils.copyProperties 无法将 String 类型转换为其他类型，需要手动转换

        // 转换坐标字段：String -> Double
        if (StringUtils.isNotBlank(triggeredRecord.getLatitude())) {
            try {
                triggeredRecordPo.setLatitude(Double.parseDouble(triggeredRecord.getLatitude()));
            } catch (NumberFormatException e) {
                log.warn("latitude 格式转换失败: {}", triggeredRecord.getLatitude(), e);
                triggeredRecordPo.setLatitude(0.0);
            }
        } else {
            triggeredRecordPo.setLatitude(0.0);
        }
        if (StringUtils.isNotBlank(triggeredRecord.getLongitude())) {
            try {
                triggeredRecordPo.setLongitude(Double.parseDouble(triggeredRecord.getLongitude()));
            } catch (NumberFormatException e) {
                log.warn("longitude 格式转换失败: {}", triggeredRecord.getLongitude(), e);
                triggeredRecordPo.setLongitude(0.0);
            }
        } else {
            triggeredRecordPo.setLongitude(0.0);
        }

        // 转换时间字段：String -> Date
        if (StringUtils.isNotBlank(triggeredRecord.getTriggerTime())) {
            try {
                triggeredRecordPo.setTriggerTime(new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").parse(triggeredRecord.getTriggerTime()));
            } catch (Exception e) {
                log.warn("triggerTime 格式转换失败: {}", triggeredRecord.getTriggerTime(), e);
            }
        }
        if (StringUtils.isNotBlank(triggeredRecord.getReceiveTime())) {
            try {
                triggeredRecordPo.setReceiveTime(new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").parse(triggeredRecord.getReceiveTime()));
            } catch (Exception e) {
                log.warn("receiveTime 格式转换失败: {}", triggeredRecord.getReceiveTime(), e);
            }
        }
        // 存储文件名，去掉 .zst 后缀
        String originalFileId = triggeredRecord.getOriginalFileId();
        if (originalFileId.endsWith(".zst")) {
            triggeredRecordPo.setOriginalFileName(originalFileId.substring(0, originalFileId.length() - 4));
        } else {
            triggeredRecordPo.setOriginalFileName(originalFileId);
        }

        // 查询全部解码规则并上传到 COS，将文件名存入 ruleFileName
        String ruleFileName = "decode-rule-" + triggeredRecordPo.getVin() + ".json";
        try {
            List<DataItemDecodeRulePo> rules = dataItemDecodeRuleService.queryAll();
            dataRuleJsonToCos(rules, ruleFileName);
            triggeredRecordPo.setRuleFileName(ruleFileName);
        } catch (Exception e) {
            log.error("上传解码规则文件失败，ruleFileName: {}", ruleFileName, e);
            // 上传失败不阻塞记录创建，ruleFileName 留空
        }

        triggeredRecordDao.insert(triggeredRecordPo);
        //写入管理触发记录任务表
        TriggeredRecordTaskPo taskPo = new TriggeredRecordTaskPo();
        taskPo.setRecordId(triggeredRecordPo.getId());
        taskPo.setTaskId(triggeredRecordPo.getOriginalFileId());
        taskPo.setTaskState(0);
        taskPo.setCreateTime(new Date());
        taskPo.setUpdateTime(new Date());
        triggeredRecordTaskDao.insert(taskPo);
        return Response.success();
    }

    /**
     * 更新数据
     *
     * @param triggeredRecord 实例对象
     * @return 实例对象
     */
    public Response update(TriggeredRecordPo triggeredRecord){
        triggeredRecordDao.update(triggeredRecord);
        return Response.success();
    }

    /**
     * 通过主键删除数据
     *
     * @param id 主键
     * @return 是否成功
     */
    public boolean deleteById(Long id){
        int total = triggeredRecordDao.deleteById(id);
        return total > 0;
    }

    @Override
    public Response updateClearTime(TriggeredRecordDTO triggeredRecord) {
        triggeredRecordDao.updateClearTime(triggeredRecord);
        return Response.success();
    }

    @Override
    public Response updateTriggerStatus(TriggeredRecordDTO triggeredRecord) {
        triggeredRecord.setAnalysisStatus(1);
        triggeredRecordDao.updateTriggerStatus(triggeredRecord);
        return Response.success();
    }

    /**
     * 将解码规则 JSON 上传到 COS
     * 参考 status-common-service 的 SparkTaskHandlerService.dataRuleJsonToCos()
     *
     * @param rules 解码规则列表
     * @param cosKey COS 文件路径
     */
    private void dataRuleJsonToCos(List<DataItemDecodeRulePo> rules, String cosKey) {
        try {
            // 转换数据格式：comparisonFieldName → displayName，新增 tagId 和 decoderParameters
            // 只处理前缀为 MIX_CUSTOM_0X81 的规则
            List<Map<String, Object>> transformedList = new ArrayList<>();
            for (DataItemDecodeRulePo rule : rules) {
                if (!rule.getDataItemCode().startsWith("MIX_CUSTOM_0X81")) {
                    continue;
                }
                Map<String, Object> item = new LinkedHashMap<>();
                item.put("dataItemCode", rule.getDataItemCode());
                item.put("decoderName", rule.getDecoderName());
                item.put("decoderParameters", null);
                item.put("tagId", "12");
                item.put("decoderParamsString", rule.getDecoderParamsString());
                item.put("displayName", rule.getComparisonFieldName());
                transformedList.add(item);
            }
            // 按 tagId 分组，key 固定为 "12"
            Map<String, List<Map<String, Object>>> result = new LinkedHashMap<>();
            result.put("12", transformedList);

            File jsonFile = File.createTempFile("decode-rule-triggered", ".json");
            ObjectMapper objectMapper = new ObjectMapper();
            objectMapper.enable(SerializationFeature.INDENT_OUTPUT);
            objectMapper.writeValue(jsonFile, result);
            boolean success = tencentCosService.putFile(cosKey, java.nio.file.Files.readAllBytes(jsonFile.toPath()));
            if (!success) {
                throw new RuntimeException("上传解码规则文件到 COS 失败");
            }
            log.info("解码规则文件已上传到 COS：{}", cosKey);
            // 清理临时文件
            if (jsonFile.exists()) {
                jsonFile.delete();
            }
        } catch (Exception e) {
            log.error("上传解码规则文件到 COS 失败", e);
            throw new RuntimeException("上传解码规则文件到 COS 失败", e);
        }
    }

    @Override
    public Response startAnalysisTask(TriggeredRecordDTO triggeredRecord) {

        TriggeredRecordPo recordPo = triggeredRecordDao.queryById(triggeredRecord.getId());

        // 创建解析任务
        AnalysisTask task = new AnalysisTask();
        Map<String, String> exportParams = new HashMap<>();
        // fileName需要带后缀
        exportParams.put("fileName", recordPo.getOriginalFileName() + tencentCosConfig.getSuffix());
        exportParams.put("cosUrl", tencentCosConfig.getCosUrl());
        exportParams.put("bucketName", tencentCosConfig.getDpBucket());
        exportParams.put("decodeRuleFileName", recordPo.getRuleFileName());
        exportParams.put("vin", recordPo.getVin());
        exportParams.put("tableName", tencentDlcConfig.getDatabaseName()+"." + recordPo.getOriginalFileName());
        task.setExportParams(exportParams);
        log.info("AnalysisTask:{}", JsonUtil.writeValueAsPrettyString(task));
        dlcService.createSparkAppTask(task);

        // 启动解析任务后，设置清除时间为当前时间 + 7 天，并重置数据删除标记
        Date clearTime = new Date(System.currentTimeMillis() + 7L * 24 * 60 * 60 * 1000);
        recordPo.setClearTime(clearTime);
        recordPo.setDataIsDelete(0);
        triggeredRecordDao.update(recordPo);
        log.info("已设置清除时间并重置data_is_delete=0，记录ID: {}, 清除时间: {}", recordPo.getId(), clearTime);

        // 保存解析任务记录
        TriggeredRecordTaskPo taskPo = new TriggeredRecordTaskPo();
        taskPo.setRecordId(recordPo.getId());
        taskPo.setTaskId(task.getSparkTaskId());
        if (StringUtils.isNotBlank(task.getSparkTaskId())) {
            taskPo.setTaskState(1);
        }else {
            taskPo.setTaskState(0);
        }
        taskPo.setCreateTime(new Date());
        taskPo.setUpdateTime(new Date());
        triggeredRecordTaskDao.insert(taskPo);

        // 启动新线程定时查询解析状态
        if (StringUtils.isNotBlank(task.getSparkTaskId())) {
            startTaskStatusMonitor(taskPo.getId(), task, triggeredRecord.getId());
        }

        return Response.success();
    }

    /**
     * 启动任务状态监控线程
     * @param taskPoId 任务记录 ID
     * @param analysisTask 分析任务对象
     * @param recordId 触发记录 ID
     */
    private void startTaskStatusMonitor(Integer taskPoId, AnalysisTask analysisTask, Long recordId) {
        CompletableFuture.runAsync(() -> {
            try {
                log.info("开始监控任务状态，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());

                int maxRetryCount = 60; // 最多查询 60 次（约 1 小时，每次间隔 60秒）
                int retryCount = 0;

                while (retryCount < maxRetryCount) {
                    TimeUnit.SECONDS.sleep(60);

                    AnalysisTask updatedTask = dlcService.describeTasks(analysisTask);
                    TaskStatus currentStatus = updatedTask.getStatus();

                    if (currentStatus == null) {
                        log.warn("任务状态为空，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());
                        currentStatus = TaskStatus.UNKNOWN;
                    }

                    log.info("任务状态更新 - 任务记录 ID: {}, Spark 任务 ID: {}, 当前状态：{}",
                            taskPoId, analysisTask.getSparkTaskId(), currentStatus.getDisplayName());

                    TriggeredRecordTaskPo taskPo = triggeredRecordTaskDao.queryById(taskPoId.longValue());
                    if (taskPo != null) {
                        //taskPo.setTaskStatus(currentStatus.name());

                        if (currentStatus == TaskStatus.SUCCESS) {
                            taskPo.setTaskState(2);
                            taskPo.setUpdateTime(new Date());
                            triggeredRecordTaskDao.update(taskPo);
                            // 更新原记录的解析状态为已解析
                            TriggeredRecordPo recordPo = triggeredRecordDao.queryById(recordId);
                            if (recordPo != null) {
                                recordPo.setAnalysisStatus(1);
                                triggeredRecordDao.update(recordPo);
                                log.info("已更新原记录解析状态为已解析，记录 ID: {}", taskPo.getRecordId());
                            }
                            //更新任务记录的状态为已解析
                            List<TriggeredRecordTaskPo> taskPoList = triggeredRecordTaskDao.queryTaskListByRecordId(recordId);
                            //查找最早时间的数据
                            TriggeredRecordTaskPo earliestTask = taskPoList.stream()
                                    .filter(t -> t.getCreateTime() != null)
                                    .min(Comparator.comparing(TriggeredRecordTaskPo::getCreateTime))
                                    .orElse(null);
                            if (earliestTask != null) {
                                earliestTask.setTaskState(2);
                                earliestTask.setUpdateTime(new Date());
                                triggeredRecordTaskDao.update(earliestTask);
                                log.info("已更新最早任务记录为已解析，任务记录 ID: {}, 创建时间: {}", earliestTask.getId(), earliestTask.getCreateTime());
                            }

                            log.info("任务执行成功，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());
                            break;
                        } else if (currentStatus == TaskStatus.FAILED ||
                                currentStatus == TaskStatus.CANCELED) {
                            taskPo.setTaskState(-1);
                            taskPo.setUpdateTime(new Date());
                            triggeredRecordTaskDao.update(taskPo);
                            log.error("任务执行失败，任务记录 ID: {}, Spark 任务 ID: {}, 状态：{}",
                                    taskPoId, analysisTask.getSparkTaskId(), currentStatus.getDisplayName());
                            break;
                        }
                    }

                    retryCount++;
                }

                if (retryCount >= maxRetryCount) {
                    log.warn("任务监控超时，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId());
                    TriggeredRecordTaskPo taskPo = triggeredRecordTaskDao.queryById(taskPoId.longValue());
                    if (taskPo != null) {
                        taskPo.setTaskState(-1);
                       // taskPo.setTaskStatus(TaskStatus.GET_EXPORT_STATUS_FAILED.name());
                        triggeredRecordTaskDao.update(taskPo);
                    }
                }

            } catch (Exception e) {
                log.error("任务状态监控异常，任务记录 ID: {}, Spark 任务 ID: {}", taskPoId, analysisTask.getSparkTaskId(), e);
                try {
                    TriggeredRecordTaskPo taskPo = triggeredRecordTaskDao.queryById(taskPoId.longValue());
                    if (taskPo != null) {
                        taskPo.setTaskState(-1);
                        taskPo.setUpdateTime(new Date());
                        //taskPo.setTaskStatus(TaskStatus.GET_EXPORT_STATUS_FAILED.name());
                        triggeredRecordTaskDao.update(taskPo);
                    }
                } catch (Exception ex) {
                    log.error("更新失败状态时出错，任务记录 ID: {}", taskPoId, ex);
                }
            }
        });
    }

