    @Override
    public List<StatisticsVo> getRecordSecondCount(TriggeredEventQuery query) {
        List<StatisticsVo> statisticsVos = Lists.newArrayList();
        List<String> timeList = DateUtils.generateSecondTimes(query.getStartTime(), query.getEndTime(), query.getInterval());
        List<StatisticsVo> list = triggeredRecordDao.getRecordSecondCount(query);
        for (int t = 0; t < timeList.size(); t++) {
            if (t > 0) {
                String startTime = timeList.get(t - 1);
                String endTime = timeList.get(t);
                String time = startTime;
                StatisticsVo statisticsVo = new StatisticsVo();
                if(query.getInterval() >= DateUtils.HOURS_IN_SECONDS_24){
                    time = DateUtils.getDayTime(startTime);
                }else if(query.getInterval() >= DateUtils.HOURS_IN_SECONDS_1){
                    time = DateUtils.getHourTime(startTime);
                }else if(query.getInterval() >= DateUtils.MINUTES_IN_SECONDS_1){
                    time = DateUtils.getMinuteTime(startTime);
                }else if (query.getInterval() >= DateUtils.SECONDS_1) {
                    time = DateUtils.getSecondsTime(startTime);
                }
                statisticsVo.setTime(time);
                statisticsVo.setStartTime(startTime);
                statisticsVo.setEndTime(endTime);
                statisticsVo.setInterval(query.getIntervalStr());
                statisticsVo.setValue(0);
                statisticsVo.setExpand(query.getExpand());

                for (StatisticsVo vo : list) {
                    if(DateUtils.isTimeInterval(vo.getTime(), startTime, endTime)) {
                        statisticsVo.setValue(vo.getValue());
                    }
                }
                statisticsVos.add(statisticsVo);
            }
        }
        return statisticsVos;
    }

