    @Override
    public void cleanExpiredData() {
        log.info("========== 开始执行数据清理任务（阶段1：清理到期数据） ==========");
        String time = DateUtils.getCurrentTime();
        log.info("当前时间：{}，查询 data_is_delete = 0 且 clear_time <= {} 的记录", time, time);

        // 查询待清理数据：data_is_delete=0 且 clear_time 已到期
        List<TriggeredRecordPo> list = triggeredRecordDao.queryDataToClean(time);
        List<String> fileNames = Lists.newArrayList();
        List<Long> recordIds = Lists.newArrayList();
        for (TriggeredRecordPo triggeredRecordPo : list) {
            fileNames.add(triggeredRecordPo.getOriginalFileName());
            recordIds.add(triggeredRecordPo.getId());
            log.info("待处理记录 - 表: TRIGGERED_RECORD, ID: {}, 文件名: {}, 清除时间: {}, VIN: {}",
                    triggeredRecordPo.getId(),
                    triggeredRecordPo.getOriginalFileName(),
                    triggeredRecordPo.getClearTime(),
                    triggeredRecordPo.getVin());
        }

        if (recordIds.isEmpty()) {
            log.info("没有需要清理的记录，任务结束");
            return;
        }

        log.info("共找到 {} 条待处理记录，开始执行清理", recordIds.size());

        // 1. TRIGGERED_RECORD_TASK: task_id无zst后缀的解析后数据标记删除
        log.info("更新表 TRIGGERED_RECORD_TASK：标记解析后数据删除，关联记录ID：{}", recordIds);
        triggeredRecordTaskDao.batchDeleteByRecordIds(recordIds);

        // 2. TRIGGERED_RECORD_TASK: task_id有zst后缀的原始文件重置为未解析
        log.info("更新表 TRIGGERED_RECORD_TASK：重置原始文件为未解析状态，关联记录ID：{}", recordIds);
        triggeredRecordTaskDao.batchResetUnparsedByRecordIds(recordIds);

        // 3. TRIGGERED_RECORD: 解析状态重置为未解析
        log.info("更新表 TRIGGERED_RECORD：标记 analysis_status=0，记录ID：{}", recordIds);
        triggeredRecordDao.batchFileIsDelete(recordIds);

        // 4. 删除对应的 DLC 表
        log.info("开始删除对应的 DLC 表，共 {} 个", fileNames.size());
        for (String fileName : fileNames) {
            try {
                String sql = "DROP TABLE IF EXISTS " + tencentDlcConfig.getDatabaseName() + ".`" + fileName + "`";
                log.info("执行 DLC DROP TABLE 语句：{}", sql);
                dlcQueryService.executeStatement(sql);
                log.info("DLC 表 {} 删除成功", fileName);
            } catch (Exception e) {
                log.error("删除 DLC 表失败，表名：{}，异常：{}", fileName, e.getMessage(), e);
            }
        }
        log.info("DLC 表删除完成");

        // 5. TRIGGERED_RECORD: 标记数据已删除（data_is_delete=1）
        log.info("更新表 TRIGGERED_RECORD：标记 data_is_delete=1，记录ID：{}", recordIds);
        triggeredRecordDao.batchDataIsDelete(recordIds);

        log.info("========== 数据清理任务（阶段1）完成 ==========");
    }

    @Override
    public void fileIsDelete() {
        log.info("========== 开始执行文件清除任务（阶段2：清理超过3年的COS文件） ==========");

        // 处理超过3年的记录：删除 COS 文件
        String threeYearsAgo = DateUtils.getPastTime(365 * 3);
        log.info("查询创建时间超过3年的记录，阈值：{}", threeYearsAgo);
        List<TriggeredRecordTaskPo> expiredTasks = triggeredRecordTaskDao.queryExpiredRecords(threeYearsAgo);
        if (CollectionUtils.isNotEmpty(expiredTasks)) {
            List<String> expiredFileNames = expiredTasks.stream()
                    .map(TriggeredRecordTaskPo::getTaskId)
                    .collect(Collectors.toList());
            log.info("共找到 {} 条超过3年的记录，开始删除 COS 文件", expiredFileNames.size());
            List<String> deletedKeys = tencentCosService.deleteFiles(expiredFileNames);
            log.info("COS 文件删除完成，成功删除：{} 个，文件列表：{}", deletedKeys.size(), deletedKeys);

            // 标记这些任务记录为已删除
            List<Integer> expiredTaskIds = expiredTasks.stream()
                    .map(TriggeredRecordTaskPo::getId)
                    .collect(Collectors.toList());
            List<Long> expiredTaskLongIds = expiredTaskIds.stream()
                    .map(Long::valueOf)
                    .collect(Collectors.toList());
            triggeredRecordTaskDao.batchDeleteByIds(expiredTaskLongIds);
            log.info("已标记超过3年的任务记录为删除，任务ID：{}", expiredTaskIds);

            // 更新 TRIGGERED_RECORD 表的 file_is_delete 为 1，is_delete 为 1
            List<Long> expiredRecordIds = expiredTasks.stream()
                    .map(TriggeredRecordTaskPo::getRecordId)
                    .distinct()
                    .collect(Collectors.toList());
            log.info("更新表 TRIGGERED_RECORD：标记 file_is_delete=1，记录ID：{}", expiredRecordIds);
            triggeredRecordDao.batchUpdateFileIsDelete(expiredRecordIds);
            log.info("更新表 TRIGGERED_RECORD：标记 is_delete=1，记录ID：{}", expiredRecordIds);
            triggeredRecordDao.batchUpdateIsDelete(expiredRecordIds);
        } else {
            log.info("没有超过3年的记录");
        }

        log.info("========== 文件清除任务（阶段2）完成 ==========");
    }

    @Override
    public void dataIsDelete() {
        // db-presto引擎暂不支持删除表
        String time = DateUtils.getPastTime(7);
        List<TriggeredRecordPo> list = triggeredRecordDao.queryDataIsDelete(time);
        List<String> tableName = Lists.newArrayList();
        List<Long> ids = Lists.newArrayList();
        for (TriggeredRecordPo triggeredRecordPo : list) {
            tableName.add(triggeredRecordPo.getOriginalFileName());
            ids.add(triggeredRecordPo.getId());
        }
        //triggeredRecordDao.batchDataIsDelete(ids);
    }


    @Override
    public ResponseEntity<byte[]> downloadFile(Long id) {
        try {
            TriggeredRecordPo recordPo = triggeredRecordDao.queryById(id);
            if (recordPo == null) {
                log.warn("下载文件失败，记录不存在，ID: {}", id);
                return ResponseEntity.badRequest().build();
            }

            if (recordPo.getFileIsDelete() != null && recordPo.getFileIsDelete() == 1) {
                log.warn("下载文件失败，文件已被删除，ID: {}, 文件名: {}", id, recordPo.getOriginalFileName());
                return ResponseEntity.badRequest().build();
            }

            String fileName = recordPo.getOriginalFileName();
            if (StringUtils.isBlank(fileName)) {
                log.error("下载文件失败，文件名为空，ID: {}", id);
                return ResponseEntity.badRequest().build();
            }

            log.info("开始下载文件，记录ID: {}, 文件名: {}", id, fileName);

            byte[] fileBytes = tencentCosService.downloadFile(fileName);
            if (fileBytes == null || fileBytes.length == 0) {
                log.error("下载文件失败，文件内容为空，ID: {}, 文件名: {}", id, fileName);
                return ResponseEntity.status(500).build();
            }

            // 下载文件名直接使用 fileName，不添加后缀
            String downloadFileName = fileName;
            String encodedFileName = URLEncoder.encode(downloadFileName, "UTF-8").replaceAll("\\+", "%20");

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_OCTET_STREAM);
            headers.setContentDispositionFormData("attachment", encodedFileName);
            headers.set(HttpHeaders.ACCESS_CONTROL_EXPOSE_HEADERS, HttpHeaders.CONTENT_DISPOSITION);
            headers.setContentLength(fileBytes.length);

            log.info("文件下载成功，记录ID: {}, 文件名: {}, 文件大小: {} bytes", id, downloadFileName, fileBytes.length);

            return ResponseEntity.ok()
                    .headers(headers)
                    .body(fileBytes);

        } catch (Exception e) {
            log.error("下载文件异常，记录ID: {}", id, e);
            return ResponseEntity.status(500).build();
        }
    }
}

