280	    private List<VehicleExcelBo> readVinFromExcel(MultipartFile file, List<Object> emptyFieldList) {
281	        List<VehicleExcelBo> vins = new ArrayList<>();
282	        Workbook workbook = null;
283	        try {
284	            workbook = WorkbookFactory.create(file.getInputStream());
285	            Sheet sheet = workbook.getSheetAt(0);
286	
287	            for (int i = 1; i <= sheet.getLastRowNum(); i++) {
288	                Row row = sheet.getRow(i);
289	                if (row != null) {
290	                    Cell cell = row.getCell(0);
291	                    if (cell != null) {
292	                        String vin = ExcelUtils.getCellStringValue(cell).trim();
293	                        if (vin != null && !vin.isEmpty()) {
294	                            VehicleExcelBo bo = new VehicleExcelBo();
295	                            bo.setModelCode( vin);
296	                            bo.setIndex(i);
297	                            vins.add(bo);
298	                        } else {
299	                            // 必填字段车型代码为空，记录到空字段列表
300	                            JSONObject emptyInfo = new JSONObject();
301	                            emptyInfo.put("index", i);
302	                            emptyInfo.put("fieldName", "车型代码");
303	                            emptyInfo.put("errorMsg", "车型代码为空");
304	                            emptyFieldList.add(emptyInfo);
305	                        }
306	                    } else {
307	                        // 单元格为空，记录到空字段列表
308	                        JSONObject emptyInfo = new JSONObject();
309	                        emptyInfo.put("index", i);
310	                        emptyInfo.put("fieldName", "车型代码");
311	                        emptyInfo.put("errorMsg", "车型代码为空");
312	                        emptyFieldList.add(emptyInfo);
313	                    }
314	                }
315	            }
316	        }catch (IOException e){
317	            log.info("文件读取异常", e);
318	        }finally {
319	            try {
320	                if (workbook != null){
321	                    workbook.close();
322	                }
323	            } catch (IOException e) {
324	                log.error("文件关闭异常", e);
325	            }
326	        }
327	        return vins;
328	    }
