            List<Integer> modelMatlabIdList = Lists.newArrayList();
            for (String modelCode : dto.getModelCodes()) {
                List<Integer> vehicleModelMatlabPoList = vehicleModelMatlabDao.queryIdsByModelCode(modelCode);
                if(CollectionUtils.isNotEmpty(vehicleModelMatlabPoList)){
                    modelCodes.add(modelCode);
                    modelMatlabIdList.addAll(vehicleModelMatlabPoList);
                }
            }
            dto.setModelCodes(modelCodes);
            dto.setModelMatlabIdList(modelMatlabIdList);
