    @Override
    public Response saveTriggeredVehicleModel(TriggeredVehicleModelDTO dto) {
        // 校验每个车型代码下 已关联数量 + 新增数量 是否超过5个
        if(CollectionUtils.isNotEmpty(dto.getModelCodes()) && CollectionUtils.isNotEmpty(dto.getTriggeredEventIds())){
            int newSize = dto.getTriggeredEventIds().size();
            for (String modelCode : dto.getModelCodes()) {
                long existCount = triggeredVehicleModelDao.countTriggeredEventIdsByModelCode(modelCode);
                if(existCount + newSize > 5){
                    return Response.error(VehicleError.VEHICLE_TRIGGERED_EVENT_IDS_EXCEED_LIMIT);
                }
            }
        }
        if(CollectionUtils.isNotEmpty(dto.getModelCodes())){
            for (String modelCode : dto.getModelCodes()) {
                if(CollectionUtils.isNotEmpty(dto.getTriggeredEventIds())){
                    for (Long triggeredEventId : dto.getTriggeredEventIds()) {
                        TriggeredVehicleModelPo po = new TriggeredVehicleModelPo();
                        po.setModelCode(modelCode);
                        po.setTriggeredEventId(triggeredEventId);
                        po.setCreateTime(new Date());
                        po.setUpdateTime(new Date());
                        po.setUserName(dto.getUserName());
                        po.setUserId(dto.getUserId());
                        triggeredVehicleModelDao.insert(po);
                    }
                }
            }
            try {
                predictiveEventSyncService.predictiveVehicleModelEventSync(dto);
            }catch (Exception e){
                log.error("请求预知事件同步接口异常:{}", e);
            }
        }
        return Response.success();
    }

