    @Override
    public void deleteTriggeredVehicleModel(List<Long> ids) {
        if(CollectionUtils.isNotEmpty(ids)){
            syncDeleteTriggeredVehicleModel(ids);
            TriggeredVehicleModelDTO dto = new TriggeredVehicleModelDTO();
            dto.setIds(ids);
            dto.setUpdateTime(new Date());
            triggeredVehicleModelDao.deleteByIds(dto);
        }
    }

    private void syncDeleteTriggeredVehicleModel(List<Long> ids) {
        Map<String, List<Long>> triggeredEventIdsByModelCode = new LinkedHashMap<>();
        for (Long id : ids) {
            TriggeredVehicleModelPo triggeredVehicleModelPo = triggeredVehicleModelDao.queryById(id);
            if (triggeredVehicleModelPo == null
                    || StringUtils.isBlank(triggeredVehicleModelPo.getModelCode())
                    || triggeredVehicleModelPo.getTriggeredEventId() == null) {
                log.warn("delete triggered vehicle model sync ignored, relationId:{}", id);
                continue;
            }
            addTriggeredEventId(triggeredEventIdsByModelCode,
                    triggeredVehicleModelPo.getModelCode(), triggeredVehicleModelPo.getTriggeredEventId());
        }

        for (Map.Entry<String, List<Long>> entry : triggeredEventIdsByModelCode.entrySet()) {
            try {
                predictiveEventSyncService.clearPredictiveEventSyncByModelCode(entry.getKey(), entry.getValue());
            } catch (Exception e) {
                log.error("request predictive event delete sync by modelCode failed, modelCode:{}, triggeredEventIds:{}",
                        entry.getKey(), JSONObject.toJSONString(entry.getValue()), e);
            }
        }
    }

    private void addTriggeredEventId(Map<String, List<Long>> triggeredEventIdsByKey, String key, Long triggeredEventId) {
        List<Long> triggeredEventIds = triggeredEventIdsByKey.computeIfAbsent(key, item -> Lists.newArrayList());
        if (!triggeredEventIds.contains(triggeredEventId)) {
            triggeredEventIds.add(triggeredEventId);
        }
    }

