    @Override
    public void templateDownload(HttpServletResponse response) {
        String fileName = "车型代码导入模板.xlsx";
        String filePath = "/template/" + fileName;
        InputStream inputStream = null;
        try {
            inputStream = getClass().getResourceAsStream(filePath);

            response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
            response.setCharacterEncoding("utf-8");
            response.setHeader("Content-Disposition",
                    "attachment;filename=" + URLEncoder.encode(fileName, "UTF-8").replaceAll("\\+", "%20"));

            OutputStream outputStream = response.getOutputStream();
            byte[] buffer = new byte[1024];
            int length;
            while ((length = inputStream.read(buffer)) > 0) {
                outputStream.write(buffer, 0, length);
            }
            outputStream.flush();
            outputStream.close();
        } catch (Exception e) {
            log.error("模板下载异常");
        } finally {
            try {
                if (inputStream != null) {
                    inputStream.close();
                }
            } catch (Exception e) {

            }
        }
    }

    @Override
    public Response batchImport(TriggeredVehicleModelDTO dto, MultipartFile file) {
        try {
            if (file.isEmpty()) {
                return Response.error(VehicleError.VEHICLE_FILE_FOUND);
            }

            List<Object> emptyFieldList = new ArrayList<>();
            List<VehicleExcelBo> vehicleExcelBoList = readVinFromExcel(file, emptyFieldList);
            ImportResultBO importResultBO = new ImportResultBO();
            importResultBO.setTotalRowNumber(vehicleExcelBoList.size() + emptyFieldList.size());
            importResultBO.setEmptyFieldList(emptyFieldList);

            // 检查是否有有效数据行（排除只有表头的情况）
            if (vehicleExcelBoList.isEmpty() && emptyFieldList.isEmpty()) {
                VehicleError error = VehicleError.VEHICLE_IMPORT_PARAM_ERROR;
                error.setErrorMessage("导入文件为空，没有数据行");
                return Response.error(error);
            }

            // 检查是否所有行的必填字段都为空
            if (vehicleExcelBoList.isEmpty() && !emptyFieldList.isEmpty()) {
                VehicleError error = VehicleError.VEHICLE_IMPORT_PARAM_ERROR;
                error.setErrorMessage("导入文件中所有行的必填字段车型代码为空，无法导入");
                return Response.error(error);
            }

            Integer correctNumber = 0;
            Integer errorNumber = 0;
            Integer succeedNumber = 0;
            List<String> succeedList = new ArrayList<>();
            List<Object> errorList = new ArrayList<>();
            for (VehicleExcelBo bo : vehicleExcelBoList){
                String code = bo.getModelCode();
                List<VehicleModelMatlabPo> vehicleList = vehicleModelMatlabDao.getVehicleByCode(code);
                if (vehicleList.size() > 0) {
                    succeedNumber ++;
                    succeedList.add( code);
                }else {
                    errorNumber ++;
                    JSONObject jsonObject = new JSONObject();
                    jsonObject.put("index", bo.getIndex());
                    jsonObject.put("code", code);
                    jsonObject.put("errorMsg", "车型代码不存在");
                    errorList.add(jsonObject);
                }
            }
            importResultBO.setCorrectNumber(correctNumber);
            importResultBO.setErrorNumber(errorNumber);
            importResultBO.setSucceedNumber(succeedNumber);
            importResultBO.setErrorList(errorList);

            if (dto.getInsert()) {
                dto.setModelCodes(succeedList);
                saveTriggeredVehicleModel(dto);
            }
            return Response.success(importResultBO);
        } catch (Exception e) {
            log.error("文件读取异常", e);
            return Response.error(VehicleError.VEHICLE_FILE_FOUND);
        }
    }

    private List<VehicleExcelBo> readVinFromExcel(MultipartFile file, List<Object> emptyFieldList) {
        List<VehicleExcelBo> vins = new ArrayList<>();
        Workbook workbook = null;
        try {
            workbook = WorkbookFactory.create(file.getInputStream());
            Sheet sheet = workbook.getSheetAt(0);

            for (int i = 1; i <= sheet.getLastRowNum(); i++) {
                Row row = sheet.getRow(i);
                if (row != null) {
                    Cell cell = row.getCell(0);
                    if (cell != null) {
                        String vin = ExcelUtils.getCellStringValue(cell).trim();
                        if (vin != null && !vin.isEmpty()) {
                            VehicleExcelBo bo = new VehicleExcelBo();
                            bo.setModelCode( vin);
                            bo.setIndex(i);
                            vins.add(bo);
                        } else {
                            // 必填字段车型代码为空，记录到空字段列表
                            JSONObject emptyInfo = new JSONObject();
                            emptyInfo.put("index", i);
                            emptyInfo.put("fieldName", "车型代码");
                            emptyInfo.put("errorMsg", "车型代码为空");
                            emptyFieldList.add(emptyInfo);
                        }
                    } else {
                        // 单元格为空，记录到空字段列表
                        JSONObject emptyInfo = new JSONObject();
                        emptyInfo.put("index", i);
                        emptyInfo.put("fieldName", "车型代码");
                        emptyInfo.put("errorMsg", "车型代码为空");
                        emptyFieldList.add(emptyInfo);
                    }
                }
            }
        }catch (IOException e){
            log.info("文件读取异常", e);
        }finally {
            try {
                if (workbook != null){
                    workbook.close();
                }
            } catch (IOException e) {
                log.error("文件关闭异常", e);
            }
        }
        return vins;
    }
