package com.ne.business.dflq.triggered.service.impl;


import com.alibaba.fastjson.JSONObject;
import com.ne.boot.common.entity.Page;
import com.ne.boot.common.entity.Response;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleDao;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleModelDao;
import com.ne.business.dflq.triggered.dao.VehicleDao;
import com.ne.business.dflq.triggered.entity.bo.ImportResultBO;
import com.ne.business.dflq.triggered.entity.bo.VehicleExcelBo;
import com.ne.business.dflq.triggered.entity.dto.TriggeredVehicleDTO;
import com.ne.business.dflq.triggered.entity.mysql.TriggeredVehiclePo;
import com.ne.business.dflq.triggered.entity.mysql.VehiclePo;
import com.ne.business.dflq.triggered.entity.query.TriggeredEventQuery;
import com.ne.business.dflq.triggered.entity.vo.TriggeredVehicleModelVo;
import com.ne.business.dflq.triggered.entity.vo.TriggeredVehicleVo;
import com.ne.business.dflq.triggered.entity.vo.VehicleVo;
import com.ne.business.dflq.triggered.error.VehicleError;
import com.ne.business.dflq.triggered.service.PredictiveEventSyncService;
import com.ne.business.dflq.triggered.service.TriggeredVehicleService;
import com.ne.business.dflq.triggered.utils.ExcelUtils;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.compress.utils.Lists;
import org.apache.commons.lang3.StringUtils;
import org.apache.poi.ss.usermodel.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.URLEncoder;
import java.util.ArrayList;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * - @ClassName: TriggeredVehicleServiceImpl
 * - @Des: 生效范围－车型代码表;(TRIGGERED_VEHICLE)表服务接口实现类
 * - @Author: xhy
 * - @Date: 2026/2/13 15:47
 **/
@Slf4j
@Service
public class TriggeredVehicleServiceImpl implements TriggeredVehicleService {

    @Autowired
    TriggeredVehicleDao triggeredVehicleDao;
    @Autowired
    VehicleDao vehicleDao;
    @Autowired
    TriggeredVehicleModelDao triggeredVehicleModelDao;
    @Autowired
    PredictiveEventSyncService predictiveEventSyncService;


    @Override
    public Response addTriggeredVehicleModel(TriggeredVehicleDTO dto) {
        if (CollectionUtils.isNotEmpty(dto.getVins())) {
            List<String> vins = Lists.newArrayList();
            for (String vin : dto.getVins()) {
                List<VehiclePo> vehicleList = vehicleDao.getVehicleByVin(vin);
                if (CollectionUtils.isNotEmpty(vehicleList)){
                    vins.add( vin);
                }
            }
            dto.setVins(vins);
            saveTriggeredVehicleModel(dto);
        }
        return  Response.success();
    }

    @Override
    public Response saveTriggeredVehicleModel(TriggeredVehicleDTO dto) {
        // 校验每个车辆VIN下 已关联数量 + 新增数量 是否超过10个
        if (CollectionUtils.isNotEmpty(dto.getVins()) && CollectionUtils.isNotEmpty(dto.getTriggeredEventIds())) {
            int newSize = dto.getTriggeredEventIds().size();
            for (String vin : dto.getVins()) {
                List<Long> existEventIds = triggeredVehicleDao.queryTriggeredEventIdsByVin(vin);
                int existSize = CollectionUtils.isNotEmpty(existEventIds) ? existEventIds.size() : 0;
                if (existSize + newSize > 10) {
                    return Response.error(VehicleError.VEHICLE_VIN_TRIGGERED_EVENT_IDS_EXCEED_LIMIT);
                }
            }
        }
        if (CollectionUtils.isNotEmpty(dto.getVins())) {
            for (String vin : dto.getVins()) {
                if (CollectionUtils.isNotEmpty(dto.getTriggeredEventIds())) {
                    for (Long triggeredEventId : dto.getTriggeredEventIds()) {
                        TriggeredVehiclePo po = new TriggeredVehiclePo();
                        po.setVin(vin);
                        po.setTriggeredEventId(triggeredEventId);
                        po.setCreateTime(new Date());
                        po.setUpdateTime(new Date());
                        po.setUserName(dto.getUserName());
                        po.setUserId(dto.getUserId());
                        triggeredVehicleDao.insert(po);
                    }
                }
            }
            try {
                predictiveEventSyncService.predictiveVehicleEventSync(dto);
            }catch (Exception e){
                log.error("请求预知事件同步接口异常:{}", e);
            }
        }
        return Response.success();
    }

    @Override
    public Response getTriggeredVehicleList(TriggeredEventQuery query) {
        query.setOffset((query.getPageIndex() - 1) * query.getPageSize());
        List<TriggeredVehicleVo> list = triggeredVehicleDao.queryTriggeredVehicleList(query);
        Long count = triggeredVehicleDao.count(query);
        Page page = new Page();
        page.setPageIndex(query.getPageIndex());
        page.setPageSize(query.getPageSize());
        page.setTotalCount(count);
        return Response.success(list, page);
    }

    @Override
    public Response getTriggeredVehicleModelList(TriggeredEventQuery query) {
        query.setOffset((query.getPageIndex() - 1) * query.getPageSize());
        List<VehicleVo> list = vehicleDao.getVehicleModel(query);
        List<String> modelCodes = new ArrayList<>();
        for (VehicleVo vo : list){
            if(StringUtils.isNotBlank(vo.getModelCode())){
                modelCodes.add(vo.getModelCode());
            }
        }
        // 车型代码为空时直接返回空结果，避免 IN () 空列表导致 SQL 语法错误
        if (CollectionUtils.isEmpty(modelCodes)) {
            Page page = new Page();
            page.setPageIndex(query.getPageIndex());
            page.setPageSize(query.getPageSize());
            page.setTotalCount(0L);
            return Response.success(new ArrayList<>(), page);
        }
        query.setModelCodeList(modelCodes);
        List<TriggeredVehicleModelVo> modelList = triggeredVehicleModelDao.queryTriggeredVehicleModelListByModelCode(query);
        Long count = triggeredVehicleModelDao.countByModelCode(query);
        Page page = new Page();
        page.setPageIndex(query.getPageIndex());
        page.setPageSize(query.getPageSize());
        page.setTotalCount(count);
        return Response.success(modelList, page);
    }

    @Override
    public void deleteTriggeredVehicleModel(List<Long>  ids) {
        if(CollectionUtils.isNotEmpty(ids)){
            syncDeleteTriggeredVehicle(ids);
            TriggeredVehicleDTO dto = new TriggeredVehicleDTO();
            dto.setIds(ids);
            dto.setUpdateTime(new Date());
            triggeredVehicleDao.deleteByIds(dto);
        }
    }

    private void syncDeleteTriggeredVehicle(List<Long> ids) {
        Map<String, List<Long>> triggeredEventIdsByVin = new LinkedHashMap<>();
        for (Long id : ids) {
            TriggeredVehiclePo triggeredVehiclePo = triggeredVehicleDao.queryById(id);
            if (triggeredVehiclePo == null
                    || StringUtils.isBlank(triggeredVehiclePo.getVin())
                    || triggeredVehiclePo.getTriggeredEventId() == null) {
                log.warn("delete triggered vehicle sync ignored, relationId:{}", id);
                continue;
            }
            addTriggeredEventId(triggeredEventIdsByVin,
                    triggeredVehiclePo.getVin(), triggeredVehiclePo.getTriggeredEventId());
        }

        for (Map.Entry<String, List<Long>> entry : triggeredEventIdsByVin.entrySet()) {
            try {
                predictiveEventSyncService.clearPredictiveEventSyncByVin(entry.getKey(), entry.getValue());
            } catch (Exception e) {
                log.error("request predictive event delete sync by vin failed, vin:{}, triggeredEventIds:{}",
                        entry.getKey(), JSONObject.toJSONString(entry.getValue()), e);
            }
        }
    }

    private void addTriggeredEventId(Map<String, List<Long>> triggeredEventIdsByKey, String key, Long triggeredEventId) {
        List<Long> triggeredEventIds = triggeredEventIdsByKey.computeIfAbsent(key, item -> Lists.newArrayList());
        if (!triggeredEventIds.contains(triggeredEventId)) {
            triggeredEventIds.add(triggeredEventId);
        }
    }

    @Override
    public void templateDownload(HttpServletResponse response) {
        String fileName = "车辆导入模板.xlsx";
        String filePath = "/template/" + fileName;
        InputStream inputStream = null;
        try {
            inputStream = getClass().getResourceAsStream(filePath);

            response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
            response.setCharacterEncoding("utf-8");
            response.setHeader("Content-Disposition",
                    "attachment;filename=" + URLEncoder.encode(fileName, "UTF-8").replaceAll("\\+", "%20"));

            OutputStream outputStream = response.getOutputStream();
            byte[] buffer = new byte[1024];
            int length;
            while ((length = inputStream.read(buffer)) > 0) {
                outputStream.write(buffer, 0, length);
            }
            outputStream.flush();
            outputStream.close();
        } catch (Exception e) {
            log.error("模板下载异常");
        } finally {
            try {
                if (inputStream != null) {
                    inputStream.close();
                }
            } catch (Exception e) {

            }
        }
    }

    @Override
    public Response batchImport(TriggeredVehicleDTO dto, MultipartFile file) {
        try {
            if (file.isEmpty()) {
                return Response.error(VehicleError.VEHICLE_FILE_FOUND);
            }

            List<Object> emptyFieldList = new ArrayList<>();
            List<VehicleExcelBo> vins = readVinFromExcel(file, emptyFieldList);
            ImportResultBO importResultBO = new ImportResultBO();
            importResultBO.setTotalRowNumber(vins.size() + emptyFieldList.size());
            importResultBO.setEmptyFieldList(emptyFieldList);

            // 检查是否有有效数据行（排除只有表头的情况）
            if (vins.isEmpty() && emptyFieldList.isEmpty()) {
                VehicleError error = VehicleError.VEHICLE_IMPORT_PARAM_ERROR;
                error.setErrorMessage("导入文件为空，没有数据行");
                return Response.error(error);
            }

            // 检查是否所有行的必填字段都为空
            if (vins.isEmpty() && !emptyFieldList.isEmpty()) {
                VehicleError error = VehicleError.VEHICLE_IMPORT_PARAM_ERROR;
                error.setErrorMessage("导入文件中所有行的必填字段VIN为空，无法导入");
                return Response.error(error);
            }

            Integer correctNumber = 0;
            Integer errorNumber = 0;
            Integer succeedNumber = 0;
            List<String> succeedList = new ArrayList<>();
            List<Object> errorList = new ArrayList<>();
            for (VehicleExcelBo bo : vins){
                String vin = bo.getVin();
                List<VehiclePo> vehicleList = vehicleDao.getVehicleByVin(vin);
                if (vehicleList.size() > 0) {
                    succeedNumber ++;
                    succeedList.add( vin);
                }else {
                    errorNumber ++;
                    JSONObject jsonObject = new JSONObject();
                    jsonObject.put("index", bo.getIndex());
                    jsonObject.put("vin", vin);
                    jsonObject.put("errorMsg", "车辆VIN不存在");
                    errorList.add(jsonObject);
                }
            }
            importResultBO.setCorrectNumber(correctNumber);
            importResultBO.setErrorNumber(errorNumber);
            importResultBO.setSucceedNumber(succeedNumber);
            importResultBO.setErrorList(errorList);

            if (dto.getInsert()) {
                dto.setVins(succeedList);
                saveTriggeredVehicleModel(dto);
            }
            return Response.success(importResultBO);
        } catch (Exception e) {
            log.error("文件读取异常", e);
            return Response.error(VehicleError.VEHICLE_FILE_FOUND);
        }
    }

    private List<VehicleExcelBo> readVinFromExcel(MultipartFile file, List<Object> emptyFieldList) {
        List<VehicleExcelBo> vins = new ArrayList<>();
        Workbook workbook = null;
        try {
            workbook = WorkbookFactory.create(file.getInputStream());
            Sheet sheet = workbook.getSheetAt(0);

            for (int i = 1; i <= sheet.getLastRowNum(); i++) {
                Row row = sheet.getRow(i);
                if (row != null) {
                    Cell cell = row.getCell(0);
                    if (cell != null) {
                        String vin = ExcelUtils.getCellStringValue(cell).trim();
                        if (vin != null && !vin.isEmpty()) {
                            VehicleExcelBo vehicleExcelBo = new VehicleExcelBo();
                            vehicleExcelBo.setIndex(i);
                            vehicleExcelBo.setVin(vin);
                            vins.add(vehicleExcelBo);
                        } else {
                            // 必填字段VIN为空，记录到空字段列表
                            JSONObject emptyInfo = new JSONObject();
                            emptyInfo.put("index", i);
                            emptyInfo.put("fieldName", "VIN");
                            emptyInfo.put("errorMsg", "VIN为空");
                            emptyFieldList.add(emptyInfo);
                        }
                    } else {
                        // 单元格为空，记录到空字段列表
                        JSONObject emptyInfo = new JSONObject();
                        emptyInfo.put("index", i);
                        emptyInfo.put("fieldName", "VIN");
                        emptyInfo.put("errorMsg", "VIN为空");
                        emptyFieldList.add(emptyInfo);
                    }
                }
            }
        }catch (IOException e){
            log.info("文件读取异常", e);
        }finally {
            try {
                if (workbook != null){
                    workbook.close();
                }
            } catch (IOException e) {
                log.error("文件关闭异常", e);
            }
        }
        return vins;
    }

    @Override
    public Response getVehicleSelectList(TriggeredEventQuery query) {
        query.setOffset((query.getPageIndex() - 1) * query.getPageSize());
        List<VehicleVo> vehicleList = vehicleDao.getSelectList(query);
        Long count = vehicleDao.getSelectCount(query);
        Page page = new Page();
        page.setPageIndex(query.getPageIndex());
        page.setPageSize(query.getPageSize());
        page.setTotalCount(count);
        return Response.success(vehicleList, page);
    }
}

