import com.ne.business.dflq.triggered.service.TriggeredVehicleService;
import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import javax.servlet.http.HttpServletResponse;

/**
 * - @ClassName: TriggeredVehicleController
 * - @Des: 生效范围－车型级表;(TRIGGERED_VEHICLE)表控制层
 * - @Author: xhy
 * - @Date: 2026/2/13 15:40
 **/
@Api(tags = "生效范围－车型代码表对象功能接口")
@RestController
@RequestMapping("/triggeredVehicle")
public class TriggeredVehicleController {

    @Autowired
    TriggeredVehicleService triggeredVehicleService;

    /**
     * 新增数据
     *
     * @param dto 实例对象
     * @return 实例对象
     */
    @ApiOperation("新增数据")
    @PostMapping(path = "/add")
    public Response add(@RequestBody TriggeredVehicleDTO dto){
        // 校验预知事件ID数量不能超过10个
        if(dto.getTriggeredEventIds() != null && dto.getTriggeredEventIds().size() > 10){
            return Response.error(VehicleError.VEHICLE_VIN_TRIGGERED_EVENT_IDS_LIMIT);
        }
        return triggeredVehicleService.saveTriggeredVehicleModel(dto);
    }

    /**
     * 分页查询
     *
     * @param query 筛选条件
     * @return 查询结果
     */
    @ApiOperation("分页查询")
    @GetMapping(path = "/list")
    public Response paginQuery(TriggeredEventQuery query){
        return triggeredVehicleService.getTriggeredVehicleList(query);
    }

    @ApiOperation("车辆级对应车型代码列表")
    @GetMapping(path = "/modelCodeList")
    public Response modelCodeList(TriggeredEventQuery query){
        return triggeredVehicleService.getTriggeredVehicleModelList(query);
    }

    /**
     * 删除数据
     *
     * @param query 主键
     * @return 删除是否成功
     */
    @ApiOperation("删除数据")
    @PostMapping(path = "/delete")
    public Response delete(@RequestBody TriggeredEventQuery query){
        triggeredVehicleService.deleteTriggeredVehicleModel(query.getId());
        return Response.success();
    }

    @ApiOperation("模板下载")
    @GetMapping(path = "/templateDownload")
    public void templateDownload(HttpServletResponse response){
       triggeredVehicleService.templateDownload(response);
    }

    @ApiOperation("导入")
    @PostMapping(path = "/batchImport")
    @NoLog
    public Response batchImport(TriggeredVehicleDTO dto, @RequestParam("file") MultipartFile file){
        return triggeredVehicleService.batchImport(dto,file);
    }

    @ApiOperation("获取车辆下拉列表")
    @GetMapping(path = "/getVehicleSelectList")
    public Response getVehicleSelectList(TriggeredEventQuery query){
        return triggeredVehicleService.getVehicleSelectList(query);
    }

}

