package com.ne.business.dflq.triggered.error;

import com.ne.boot.common.exception.IError;


public enum DataError implements IError {
    /**
     * 车辆不存在
     */
    DAT_DATE_ERROR("0001", "数据格式异常"),
    DAT_AUTH_ERROR("0002", "车辆未实名认证，无可查远控记录"),
    REQ_PARAM_IS_NULL("0003", "必填参数不能为空 - aid/uuid"),

    // 文件不存在
    FILE_NOT_EXIST("0004", "文件不存在");


    /**
     * 错误码
     */
    String errorCode;
    String errorMessage;
    private static final String ns = "DataError";

    DataError(String errorCode, String errorMessage) {
        this.errorCode = errorCode;
        this.errorMessage = errorMessage;
    }

    public String getNamespace() {
        return ns;
    }

    public String getErrorCode() {
        return ns + "_" + errorCode;
    }

    public String getErrorMessage() {
        return errorMessage;
    }

    public void setErrorMessage(String msg) {
        this.errorMessage = msg;
    }
}

