package com.ne.business.dflq.triggered.service.impl;


import com.alibaba.fastjson.JSONObject;
import com.ne.boot.common.entity.Page;
import com.ne.boot.common.entity.Response;
import com.ne.business.dflq.triggered.dao.TriggeredEventDao;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleDao;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleModelDao;
import com.ne.business.dflq.triggered.entity.mysql.TriggeredEventPo;
import com.ne.business.dflq.triggered.entity.mysql.TriggeredRulePo;
import com.ne.business.dflq.triggered.entity.query.TriggeredEventQuery;
import com.ne.business.dflq.triggered.entity.vo.TriggeredEventRuleVo;
import com.ne.business.dflq.triggered.entity.vo.TriggeredEventVo;
import com.ne.business.dflq.triggered.error.DataError;
import com.ne.business.dflq.triggered.service.TriggeredEventRuleService;
import com.ne.business.dflq.triggered.service.TriggeredEventService;
import com.ne.business.dflq.triggered.service.TriggeredRuleService;
import com.ne.business.dflq.triggered.service.PredictiveEventSyncService;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.*;

import static com.ne.business.dflq.triggered.common.CommonConstant.RULE_VERSION_PREFIX;

/**
 * - @ClassName: TriggeredEventServiceImpl
 * - @Des: 预知事件
 * - @Author: xhy
 * - @Date: 2026/2/11 16:02
 **/
@Slf4j
@Service
public class TriggeredEventServiceImpl implements TriggeredEventService {

    @Autowired
    TriggeredEventDao triggeredEventDao;
    @Autowired
    TriggeredVehicleDao triggeredVehicleDao;
    @Autowired
    TriggeredVehicleModelDao triggeredVehicleModelDao;
    @Autowired
    TriggeredEventRuleService triggeredEventRuleService;
    @Autowired
    TriggeredRuleService triggeredRuleService;
    @Autowired
    PredictiveEventSyncService predictiveEventSyncService;

    @Override
    public void saveTriggeredEvent(TriggeredEventVo eventVo) {
        TriggeredEventPo event = new TriggeredEventPo();
        event.setEventName(eventVo.getEventName());
        event.setEventDesc(eventVo.getEventDesc());
        event.setCanPlatform(eventVo.getCanPlatform());
        event.setCreateTime(new Date());
        event.setUpdateTime(new Date());
        event.setUpdateBy(eventVo.getUserName());
        event.setUserId(eventVo.getUserId());
        event.setUserName(eventVo.getUserName());
        event.setRuleInfo(JSONObject.toJSONString(eventVo.getEventRule()));
        String version = getNextVersion("");
        event.setRuleVersion(version);
        triggeredEventDao.saveTriggeredEvent(event);
        Long eventId = event.getId();
        if(eventVo.getEventRule() != null){
            TriggeredRulePo rule = new TriggeredRulePo();
            rule.setName(version);
            rule.setTriggeredEventId(eventId);
            rule = triggeredRuleService.insert(rule);
            Long ruleId = rule.getId();
           for (TriggeredEventRuleVo ruleVo : eventVo.getEventRule()){
               ruleVo.setTriggeredEventId(eventId);
               ruleVo.setVersion(version);
               ruleVo.setRuleId(ruleId);
               triggeredEventRuleService.saveTriggeredEventRule(ruleVo);
           }
            triggeredEventDao.updateRuleId(eventId, ruleId);
        }
    }

    @Override
    public Response getTriggeredEventList(TriggeredEventQuery query) {
        query.setOffset((query.getPageIndex() - 1) * query.getPageSize());
        List<TriggeredEventPo> list = triggeredEventDao.getTriggeredEventList(query);
        Long count = triggeredEventDao.getTriggeredEventCount(query);
        Page page = new Page();
        page.setPageIndex(query.getPageIndex());
        page.setPageSize(query.getPageSize());
        page.setTotalCount(count);
        return Response.success(list, page);
    }

    @Override
    public void deleteTriggeredEvent(Long id) {
        if (id == null) {
            log.warn("delete triggered event ignored, id is null");
            return;
        }
        try {
            predictiveEventSyncService.clearPredictiveEventSync(id);
        } catch (Exception e) {
            log.error("request predictive event delete sync failed, triggeredEventId:{}", id, e);
        }
        Date updateTime = new Date();
        triggeredEventDao.deleteById(id);
        triggeredEventRuleService.deleteByEventId(id);
        triggeredVehicleDao.deleteByTriggeredEventId(id, updateTime);
        triggeredVehicleModelDao.deleteByTriggeredEventId(id, updateTime);
    }

    @Override
    public Response getTriggeredEventById(Long id, String version) {
        TriggeredEventPo event = triggeredEventDao.getById(id);
        TriggeredEventVo eventVo = new TriggeredEventVo();
        eventVo.setId(event.getId());
        eventVo.setEventName(event.getEventName());
        eventVo.setEventDesc(event.getEventDesc());
        eventVo.setCanPlatform(event.getCanPlatform());
        eventVo.setRuleVersion(event.getRuleVersion());
        eventVo.setUserId(event.getUserId());
        eventVo.setUserName(event.getUserName());
        if(StringUtils.isNotBlank(event.getRuleVersion())){
            eventVo.setRuleVersions(Arrays.asList(event.getRuleVersion().split(",")));
        }
        List<TriggeredEventRuleVo> ruleList = triggeredEventRuleService.getEventRuleByEventId(id, version);
        eventVo.setEventRule(ruleList);
        return Response.success(eventVo);
    }

    @Override
    public Response updateTriggeredEvent(TriggeredEventVo eventVo) {
        TriggeredEventPo event = new TriggeredEventPo();
        event.setId(eventVo.getId());
        event.setEventName(eventVo.getEventName());
        event.setEventDesc(eventVo.getEventDesc());
        event.setCanPlatform(eventVo.getCanPlatform());
        event.setUpdateTime(new Date());
        event.setUpdateBy(eventVo.getUserName());
        String version = null;
        if(eventVo.getNewVersion() != null){
            try {
                version = getNextVersion(eventVo.getRuleVersion());
            } catch (NumberFormatException e) {
                log.error("版本号转换异常", e);
                return Response.error(DataError.DAT_AUTH_ERROR);
            }
            TriggeredRulePo rule = new TriggeredRulePo();
            rule.setName(version);
            rule.setTriggeredEventId(event.getId());
            rule = triggeredRuleService.insert(rule);
            Long ruleId = rule.getId();
            for (TriggeredEventRuleVo ruleVo : eventVo.getEventRule()){
                ruleVo.setTriggeredEventId(event.getId());
                ruleVo.setVersion(version);
                ruleVo.setRuleId(ruleId);
                triggeredEventRuleService.saveTriggeredEventRule(ruleVo);
                if(Objects.isNull(eventVo.getIsRuleVersion()) || eventVo.getIsRuleVersion() == 1){
                    triggeredEventDao.updateRuleId(eventVo.getId(), ruleId);
                }
            }
        }
        if(version != null){
            event.setRuleVersion(eventVo.getRuleVersion() + "," +  version);
        }else {
            event.setRuleVersion(eventVo.getRuleVersion());
        }
        event.setRuleInfo(JSONObject.toJSONString(eventVo.getEventRule()));
        triggeredEventDao.updateTriggeredEvent(event);
        return Response.success();
    }

    @Override
    public Response getTriggeredEventVehicleModelList(TriggeredEventQuery query) {
        query.setOffset((query.getPageIndex() - 1) * query.getPageSize());
        List<TriggeredEventVo> list = triggeredEventDao.getTriggeredEventVehicleModelList(query);
        Long count = triggeredEventDao.getTriggeredEventVehicleModelCount(query);
        Page page = new Page();
        page.setPageIndex(query.getPageIndex());
        page.setPageSize(query.getPageSize());
        page.setTotalCount(count);
        return Response.success(list, page);
    }

    @Override
    public Response getTriggeredEventVehicleList(TriggeredEventQuery query) {
        query.setOffset((query.getPageIndex() - 1) * query.getPageSize());
        List<TriggeredEventVo> list = triggeredEventDao.getTriggeredEventVehicleList(query);
        Long count = triggeredEventDao.getTriggeredEventVehicleCount(query);
        Page page = new Page();
        page.setPageIndex(query.getPageIndex());
        page.setPageSize(query.getPageSize());
        page.setTotalCount(count);
        return Response.success(list, page);
    }

    private String getNextVersion(String versionStr) throws NumberFormatException{
        if (versionStr == null || versionStr.trim().isEmpty()) {
            return RULE_VERSION_PREFIX + "1";
        }

        int maxVersion = 0;
        String[] versions = versionStr.split(",");

        for (String version : versions) {
            version = version.trim();
            if (version.startsWith(RULE_VERSION_PREFIX)) {
                String versionNum = version.replaceAll(RULE_VERSION_PREFIX, "");
                int v = Integer.parseInt(versionNum);
                if (v > maxVersion) {
                    maxVersion = v;
                }
            }
        }
        return RULE_VERSION_PREFIX + (maxVersion + 1);
    }

    @Override
    public Response getSelectList(TriggeredEventQuery query) {
        List<TriggeredEventVo> list = triggeredEventDao.getSelectList(query);
        return Response.success(list);
    }

    @Override
    public List<String> queryEventNameByIdList(List<Long> ids) {
        return triggeredEventDao.selectEventNameByIdList(ids);
    }

    @Override
    public Response getRuleListByEventId(Long id) {
        List<TriggeredRulePo> list = triggeredRuleService.queryRuleByTriggeredEventId(id);
        return Response.success(list);
    }

    @Override
    public Response updateRuleId(TriggeredEventVo eventVo) {
        triggeredEventDao.updateRuleId(eventVo.getId(), eventVo.getRuleId());
        return Response.success();
    }
}

