package com.ne.business.dflq.triggered.kafka;

import com.alibaba.fastjson.JSON;
import com.ne.boot.common.util.JsonUtil;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleDao;
import com.ne.business.dflq.triggered.entity.dto.TriggeredRecordDTO;
