package com.ne.business.dflq.triggered.kafka;

import com.alibaba.fastjson.JSON;
import com.ne.boot.common.util.JsonUtil;
import com.ne.business.dflq.triggered.dao.TriggeredVehicleDao;
import com.ne.business.dflq.triggered.entity.dto.TriggeredRecordDTO;
import com.ne.business.dflq.triggered.service.TriggeredEventService;
import com.ne.business.dflq.triggered.service.TriggeredRecordService;
import com.ne.dflq.bp.vo.PredictiveDataVo;
import com.ne.ice.tbox.protocol.TboxTspProtocolDecoder;
import com.ne.ice.tbox.protocol.dto.DecodeMixC6Result;
import com.ne.ice.tbox.protocol.dto.PredictiveEventData;
import com.ne.ice.tbox.protocol.dto.TboxMessagePlus;
import com.ne.ice.tbox.protocol.enums.VapGatewayType;
import com.ne.ice.tbox.protocol.utils.ByteUtils;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;

import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.stream.Collectors;



@Slf4j
@Component
public class TriggeredEventListener {

    @Autowired
    TriggeredEventService triggeredEventService;
    @Autowired
    TriggeredRecordService triggeredRecordService;
    @Autowired
    TriggeredVehicleDao triggeredVehicleDao;

    private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    @KafkaListener(id = "${spring.kafka.properties.triggeredEventTopic:predictive_event}", topics = {"${spring.kafka.properties.triggeredEventTopic:predictive_event}"}, idIsGroup = false, groupId = "${spring.kafka.consumer.group.id:triggered_event}", containerFactory = "kafkaListenerContainerFactory")
    protected void listen(final List<String> list) {
        if (CollectionUtils.isNotEmpty(list)) {
            for (String s : list) {
                try {
                    if (StringUtils.isBlank(s)) {
                        return;
                    }
                    PredictiveDataVo predictiveDataVo = JSON.parseObject(s, PredictiveDataVo.class);
                    Long gatewayReceiveTime = predictiveDataVo.getGatewayReceiveTime();
                    // 如果 gatewayReceiveTime 为空或为0，使用当前时间
                    if (gatewayReceiveTime == null || gatewayReceiveTime == 0L) {
                        gatewayReceiveTime = System.currentTimeMillis();
                    }
                    TboxMessagePlus tboxMessagePlus = TboxTspProtocolDecoder.decodeHeader(ByteUtils.hexStringToByteArray(predictiveDataVo.getHex()), VapGatewayType.MIX_GATEWAY, gatewayReceiveTime);
                    DecodeMixC6Result decodeMixC6Result = TboxTspProtocolDecoder.decodeMixDataC6(tboxMessagePlus);
                    //本次触发的预知事件列表
//                    List<PredictiveEventData> predictiveEventDataList = decodeMixC6Result.getPredictiveEventDataList();
                    //获得原始数据文件ID
                    List<Long> eventIdList=  decodeMixC6Result.getPredictiveEventDataList().stream().map(PredictiveEventData::getEventId).collect(Collectors.toList());
                    //获得使用规则ID
                    List<Long> eventRuleIdList = decodeMixC6Result.getPredictiveEventDataList().stream().map(PredictiveEventData::getEventRuleId).collect(Collectors.toList());
                    // 优先使用 Kafka 消息中的 eventId 查询事件名称
                    List<String> eventNameList = triggeredEventService.queryEventNameByIdList(eventIdList);

                    // 兜底：如果通过 eventId 查不到，通过 VIN 关联 TRIGGERED_VEHICLE 查询
                    if (CollectionUtils.isEmpty(eventNameList)) {
                        String vin = tboxMessagePlus.getVin();
                        log.info("通过eventId未查到事件名称，尝试通过VIN查询, vin: {}", vin);
                        List<Long> vehicleEventIds = triggeredVehicleDao.queryTriggeredEventIdsByVin(vin);
                        if (CollectionUtils.isNotEmpty(vehicleEventIds)) {
                            eventNameList = triggeredEventService.queryEventNameByIdList(vehicleEventIds);
                            log.info("通过VIN查询到事件: {}", eventNameList);
                        }
                    }

                    // 转换时间戳为 yyyy-MM-dd HH:mm:ss 格式
                    String triggerTimeString = decodeMixC6Result.getTriggerTimestamp() != null ? DATE_FORMAT.format(new Date(decodeMixC6Result.getTriggerTimestamp())) : null;
                    String gatewayReceiveTimeString = DATE_FORMAT.format(new Date(gatewayReceiveTime));

                    for (int i=0;i<eventIdList.size();i++){
                        //截取文件名
                        String filename = predictiveDataVo.getUrl().substring(predictiveDataVo.getUrl().lastIndexOf('/') + 1);
                        filename = filename.split("\\?")[0];
                        // 每条记录使用对应的事件名称，而不是所有事件名称的连接
                        String eventName = (i < eventNameList.size()) ? eventNameList.get(i) : "";
                        triggeredRecordService.insert(new TriggeredRecordDTO(null, Math.toIntExact(eventIdList.get(i)), filename, triggerTimeString, gatewayReceiveTimeString, 0, null, null, 0, null, decodeMixC6Result.getPositioningStatus(), decodeMixC6Result.getLatitude().toString(), decodeMixC6Result.getLongitude().toString(), eventName, tboxMessagePlus.getVin(), Math.toIntExact(eventRuleIdList.get(i))));
                    }
                } catch (Exception e) {
                    log.error("topic triggered_event - handler error data:{}", s, e);
                }
            }
        }
    }
}

